INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('restaurant-usp-what-is-it-and-why-does-it-matter', 'Restaurant USP: What Is It and Why Does It Matter?', 'When it comes to restaurant marketing, it’s important to identify your business aspects that set you apart. Everyone has at least one detail that makes a loyal customer say to their friend, “You should try this place;...', '[{"type":"p","text":"When it comes to restaurant marketing, it’s important to identify your business aspects that set you apart. Everyone has at least one detail that makes a loyal customer say to their friend, “You should try this place; they’ve got great dinner specials!” or something similar. Your USP should define what makes dining with you a one-of-a-kind experience and naturally increase profit as a result."},{"type":"p","text":"You can generate good ideas for a USP by identifying the business aspects that matter to your existing base. How do you positively influence their lives? What moral cause are they aligned with that you can demonstrate you care about too? Maybe a new green initiative, organic food, or seamless contactless experience is enough to sway new customers to your side."},{"type":"h2","text":"Finding the Right USP"},{"type":"p","text":"A nappy, short explanation of what you do best goes a long way, and it doesn’t have to be an objective quality. You don’t need to be voted the best burger in the state to have people recommend you for lunch because the meat is juicy and the buns are delicious. Other common USPs include:"},{"type":"p","text":"1. Something that stands out about your customer service."},{"type":"p","text":"2. Interesting menu items, whether it’s locally-sourced produce or foreign cuisine or something else."},{"type":"p","text":"3. Unbeatable prices."},{"type":"p","text":"4. Eye-catching decor and a nice ambiance."},{"type":"p","text":"As usual, your customers are the most valuable source of information. Ask them directly what they like about coming to your restaurant, why they recommend you to their friends, and what they say when they tell someone new to try you out. This way, you’ll get a sense of what USPs already work for your business, so you can lean into and improve upon what you know will be a hit. Consolidate multiple different selling points to create the ultimate USP for your restaurant."},{"type":"h2","text":"Using USPs"},{"type":"p","text":"Strong customer relationships are vital for forming a successful USP. Spend time getting to know your most loyal patrons and get a sense of what, precisely, they enjoy about your business, as this is what future customers are likely to find valuable as well. It helps tailor marketing campaigns to reach your ideal audience, who in turn will tell their like-minded friends, and so on in a never-ending circle of professional growth."},{"type":"p","text":"When it comes to smarter marketing and safely storing customer data, you need superior restaurant technology. Leverage customer information effectively to find their preferences and create compelling promotions. To do that, you need software that operates smoothly alongside your workforce. Don’t rely on slow or failing devices; get restaurant technology that works at business speed."},{"type":"p","text":"Schedule a demo with eatOS to learn how we’re ushering in the future of food service, today."},{"type":"p","text":"#eatOS #RestaurantMarketing"}]', 'https://static.wixstatic.com/media/a77ed6_ca1e6dca57c24659ad57a53caedb314c~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2022-09-28', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('restaurants-add-qr-codes-to-the-menu', 'Restaurants Add QR Codes to the Menu', 'Smart restaurateurs are always looking to push the envelope when it comes to running a successful business in the modern age. This means equipping the restaurant with state-of-the-art technology that facilitates...', '[{"type":"p","text":"Smart restaurateurs are always looking to push the envelope when it comes to running a successful business in the modern age. This means equipping the restaurant with state-of-the-art technology that facilitates ordering and payment, thus improving the overall guest experience for present and future customers."},{"type":"p","text":"Lately, restaurants have enjoyed the benefits they get when they discover QR code ordering. eatOS offers this capability for all of our merchant partners because we believe that everyone deserves affordable cutting-edge technology that will make their restaurant thrive."},{"type":"h2","text":"What is QR code ordering?"},{"type":"p","text":"Before you implement a system involving QR code ordering, first you need to understand what it is and how it works."},{"type":"p","text":"Restaurants post a QR code somewhere on the premises for guests to scan with their phones, which then automatically brings up an online menu for them to browse and buy from. It works with any phone camera and doesn’t require the customer to download an app first. Unlike most vendors, eatOS doesn’t simply scan the menu for easy viewing: We create an actual menu optimized for mobile screens, with all the same capability as an online menu viewed through desktop computer."},{"type":"p","text":"To make the most of QR capability, we recommend placing the code somewhere visible and highly trafficked so more customers will notice and use it. Place it in an existing table stand, incorporate it into the decor as a sign or wall sticker, post in the storefront window or simply have a server present it to the table."},{"type":"h2","text":"Why do customers prefer QR ordering?"},{"type":"p","text":"It saves time to tap and order right from their seat. As soon as a customer knows what they want, they can input it directly to the kitchen instead of waiting for a server to come around and write it down and then run it to the back of the house. Self-service capabilities improve accuracy so customers get their food quicker and with fewer human errors. It’s a straightforward system: Just scan, browse and pay right from the table. Self-ordering is faster and easier than ever with our clean, intuitive interface and virtual menus."},{"type":"p","text":"Our QR feature comes at the perfect time, too: With COVID-19 still a paramount concern for consumers and businesses alike, having a reliable contact-free method for ordering and transactions encourages people to choose your restaurant on the rarer occasions that they dine out, especially over your competitors who dont have as many COVID-19 protections in place. eatOS lets your customers and staff social distance, which is more important now than ever before."},{"type":"p","text":"Keep the simplicity going, right down to the final transaction. Your customers can pay from the same sceen so they don’t have to wait for servers to bring the check or go through the Point of Sale system. The restaurant experience has never been safer, more socially distant or easier to navigate with just the phone in your hands."},{"type":"h2","text":"Why do restaurants need it?"},{"type":"p","text":"QR codes make ordering easy, for both to-go and dine-in. If for no other reason, then restaurants need QR ordering because their customers expect it. With COVID-19 still a significant problem, restaurants need to invest in a variety of contact-free solutions that protect the health and safety of their guests and employees alike. Its a changing marketplace and these trends will likely continue to grow."},{"type":"p","text":"Make QR codes work alongside the rest of your technology. For example, our Point of Sale lets customers scan and pay with the cashier without handing over a card, instead working with their online wallets. For full service restaurants, the QR code automatically keeps track of what table each order belongs to so food running stays simple, but customers can add items or close out the check whenever they want. Splitting the check is similarly simple with eatOS hard- and software to provide the best possible customer experience."},{"type":"p","text":"Additionally, QR code ordering gets you the lowdown on all of your customers. Collect data and analytics on the guests in your restaurant, which will help you make better budgeting and business decisions and can even drive more successful marketing campaigns. Youll wonder how you ever operated any other way."},{"type":"p","text":"Get the advanced features and technology that your customers are craving, your competition is considering and your restaurant really needs. Learn more about what contactless payment methods can do for you, and book a demo with eatOS to find out what we can do to help bring your restaurant into the future of food service."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #eatOS #OnlineOrdering #ContactlessPayment #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_9da28f1d21e24842ae16ca55f2bb6605~mv2.jpg', 'Restaurant Insights', 'eatOS Staff', '2022-09-27', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('restaurants-retake-control-from-3rd-party-apps', 'Restaurants Retake Control from 3rd Party Apps', 'Third party delivery services got a lot of restaurants through the pandemic. When lockdown started, any food service that didn’t offer delivery and takeout had to find a way to start those channels quickly. Soon,...', '[{"type":"p","text":"Third party delivery services got a lot of restaurants through the pandemic. When lockdown started, any food service that didn’t offer delivery and takeout had to find a way to start those channels quickly. Soon, though, more restaurants found that they would rather open their own service than pay the hefty commissions often associated with third parties."},{"type":"p","text":"But even if you got off the apps, trouble might not end there. Multiple restaurants report that third parties like Uber and Grubhub continued to list their restaurants without permission. They order by proxy and pick it up like a regular delivery. But does this hurt sales?"},{"type":"p","text":"Image by mohamed Hassan from Pixabay"},{"type":"h2","text":"Why Not 3rd Party Apps?"},{"type":"p","text":"Restaurants who use their own channels have more control over the experience. If food arrives in poor quality or takes a long time, guests will take it up with you, not the 3rd party. In this competitive market, it’s especially important to address problems quickly and efficiently, or else you risk negative reviews and lose loyalty. Restaurants have reported even further issues like old menus being uploaded and incorrect prices. This makes it tough to stay competitive, particularly if you offer rotating seasonal menus that rely on what’s in-style."},{"type":"p","text":"Meanwhile, this hurts staff too. Instead of receiving money from tips, it goes to outside parties. Restaurants have a labor shortage, and you want to nurture better job satisfaction, not frustration over lost wages."},{"type":"p","text":"Some restaurants had this problem continue even after phoning in about it multiple times, too. If they aren’t putting themselves on the apps willingly, and they can’t take themselves off of automatic sign-ups, what are restaurants supposed to do?"},{"type":"h2","text":"Restaurants Find Even Ground"},{"type":"p","text":"It’s hard to fight the will of a major company, who has much more resources and time than local eateries. That’s why restaurants have felt so powerless in the past. Now, New York state may outlaw the practice of listing restaurants without clear permission. Noncompliance could cost 3rd party apps as much as $1K per day, per restaurant. They may also face additional legal action from individual restaurants. It has a serious effect on their brand and success, particularly during this tenuous recovery period, and they have a right to be mad."},{"type":"p","text":"Early in the pandemic, states passed temporary emergency measures to help restaurants that didn’t have takeout or delivery, but needed it to survive. They capped commission fees on 3rd party platforms so that restaurants could use them to grow new sales channels. However, all these temporary laws will soon expire. Restaurants are simultaneously pushing to either expand these support services or at least make the fee structure more transparent when they sign up."},{"type":"p","text":"In response to all this, 3rd party apps replied that they’re working on making communication clearer and more accessible. Restaurants who do find issues, from unwanted listings to incorrect menu options, can then fix them quickly. Still, without state-enacted protections for small businesses, restaurants have to rely on the apps’ word. Instead, small businesses are pushing for legislation that provides long-term solutions. They need protection throughout the recovery period and beyond."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #Restaurant #RestaurantBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_a8cddd4e50c743228d097f5ec715f029~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-09-22', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('should-your-restaurant-offer-meal-kits', 'Should Your Restaurant Offer Meal Kits?', 'The pandemic has hit everyone hard, from customers to business owners. The restaurant industry hurts particularly hard. As a result, owners and managers found new solutions to the common problem: _How can we make enough...', '[{"type":"p","text":"The pandemic has hit everyone hard, from customers to business owners. The restaurant industry hurts particularly hard. As a result, owners and managers found new solutions to the common problem: _How can we make enough revenue to survive?_ The answer, interestingly enough, lies with meal kits."},{"type":"p","text":"Many consumers can’t afford to or don’t want to risk dining out. Delivery, takeout, and curbside services all surged in popularity to meet growing demand this year, but it’s not enough. To help families in need, businesses have begun experimenting with new ideas."},{"type":"h2","text":"The Next Big Thing?"},{"type":"p","text":"Long months spent isolated inside have grated on your best customers. They need meal kits to weather the rest of the pandemic. Dole out best-selling dishes, specials you don’t usually offer, or a signature spin on a staple food. Customers will flock to purchase a kit, boosting your sales and helping your business survive the pandemic."},{"type":"p","text":"What else do meal kits do?"},{"type":"p","text":"1. Connect customers to your food even if they can’t enjoy it in the peace and ambiance of your indoor seating area. Instead, they’ll have the tools they need for a taste of your best cooking, from the comfort of their own homes."},{"type":"p","text":"2. Add shipping on top of pickup options and garner more new customers. If they’re satisfied enough, they’ll think of you after the pandemic when they want to satisfy this same craving."},{"type":"p","text":"3. Give guests something to do together to pass the time. They’ll enjoy a group activity and reap the rewards at the end with a family dinner to appreciate what they all made."},{"type":"p","text":"4. Skip the dangers of a grocery line and the frustrations of having to decide what to make for dinner. Meal kits are a convenient way to get everything sent right to the front door."},{"type":"p","text":"5. Stay fresh in customers’ minds. When they’re not actively visiting, you could slip out of their daily routine and they’ll forget about you in the meantime."},{"type":"h2","text":"Making Meal Kits a Success"},{"type":"p","text":"You get an additional bonus when selling meal kits compared to serving sit-down meals: User-generated content. Also known as UGC, this refers to any post your followers make on social media when they tag your restaurant, check-in with geo-location, or even just post a photo of their finished meal thanking you for the time spent with family. Make sure to repost, share, like and spend time on fans’ pages to show you’ve noticed their patronage and appreciate the free publicity. Successful restaurants need strong customer relationships."},{"type":"p","text":"Social media is a great place to get to know your customers on a personal level, which also makes it the perfect arena to announce your new venture. By integrating yourself into their daily feed you guarantee the most loyal of them will see your announcements."},{"type":"p","text":"Add links to the right landing page on your socials and promote those posts for a wider audience to see. Every click matters, so make sure to properly utilize social media. To reach the most viewers possible, your pages need to do their part by generating clicks and sales for your meal kits."},{"type":"p","text":"The future of foodservice lies in your online presence. Is your restaurant ready to face the challenge?"},{"type":"p","text":"#eatOS #CoronavirusPandemic #Covid19Pandemic #MealKit #RestaurantBusiness #CustomerService #Restaurant #CustomerRelationships"}]', 'https://static.wixstatic.com/media/a77ed6_739ed4e7cbbf48d698d5ea1ee02c0e7e~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-09-20', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('so-you-want-to-start-catering', 'So You Want to Start Catering?', 'When its done right, catering drastically increases revenue for restaurants. Dining out was becoming a more and more popular option even before COVID-19. Catering is a multibillion dollar industry, and a lot of full...', '[{"type":"p","text":"When its done right, catering drastically increases revenue for restaurants. Dining out was becoming a more and more popular option even before COVID-19. Catering is a multibillion dollar industry, and a lot of full service restaurants want in on that profit."},{"type":"p","text":"If your restaurant is thinking about doing catering, you might assume that you just have to choose whether to serve food buffet-style or plated and brought out to the guests. In reality, that’s only the tip of the iceberg when it comes to establishing this new venture."},{"type":"h2","text":"Creating the Perfect Menu"},{"type":"p","text":"The first thing you need is, of course, a menu of what you can offer at the event. It’s a good idea to use classics and fan favorites from your sit-down restaurant’s menu, because guests are almost guaranteed to love them. You can trade some menu items that wouldn’t work for catering for dishes that sit better or can be more easily made in bulk. Don’t be afraid to add sandwiches: They’re a well-known staple for a reason, and an easy choice for picky eaters who can’t settle on anything else."},{"type":"p","text":"With that in mind, you should always include menu options for common dietary restrictions like vegetarianism and veganism, or dairy, nut and gluten allergies to name just a few. You can also ask clients whether they know of any restrictions in their party so you can set aside something special."},{"type":"p","text":"The ingredients themselves matter, too. Different customers value different approaches, for example if you choose a rotational menu that changes with the seasons you can use farm-fresh and organic ingredients which taste better and make for fresher dishes. Of course, farm-to-table methods require you to edit and swap out menu options more often, which is a time commitment however it will reflect company values that attract certain customers more than others. It all depends on your existing customer base, target audience, and priorities in this new venture."},{"type":"p","text":"Once you decide what goes on it, now you need to price the menu. It should be similar in price and quality to your restaurant menu, since that’s what has come to be associated with your brand. You can factor in more exact prices either by looking at costs per plate (total food cost divided by total guests served) or by calculating the cost per person (gross revenue minus the cost of food, labor and materials)."},{"type":"p","text":"Adding a little bit of creativity to your menu goes a long way toward standing out from the crowd. Creating themed menus is good if you have unique dishes or a specific cultural or signature theme at your restaurant, as this will help carry your brand identity into each and every event. Youll stand out more prominently in guests’ memories, maybe enough that they come try out your cuisine at the restaurant for a sit-down dinner. Themed menus can really make an impression."},{"type":"h2","text":"Building a Client Base"},{"type":"p","text":"Now that the menu is settled, you need to garner some clientele. First decide when you plan to offer catering services so you know who to advertise to; May to September, also known as wedding season, is very profitable and thus a common choice for caterers who are just starting out. However just because its the most popular doesn’t mean that you should limit yourself to these months. Events happen all year round. Of course, catering takes time and resources so it all depends on what you can afford. There isnt one right answer. Try different clients, events and times of year to find a model that works best for your business."},{"type":"p","text":"When you have your menu and calendar set, it’s time to start sourcing some clients. Networking is a major part of the catering industry, which is why you should host tasting events to give potential clients a feel for how it would be to hire you for their party. Curate a list of leads and invite them to a tasting event at your restaurant, as this has the double advantage of drawing attention to your restaurant and your new venture. Then get ready to network. Keep brochures, takeaway menus and business cards on hand to give out to anyone who seems interested. Things like discounts on their first booking or referral bonuses also go a long way toward securing new clients."},{"type":"p","text":"People won’t know you’ve started catering unless you tell them. Creative marketing techniques distinguish you from the crowd, so consider using other avenues besides traditional print methods or standard ads. Find your signature slogan, picture or something else unorthodox that identifies you and makes you stand out."},{"type":"p","text":"Lastly, your staff should be well-trained to handle any catering requests that walk in the door, no matter what else is going on at the time. They should have the catering menu on hand and know the proper procedure to make that sale."},{"type":"h2","text":"Start Catering"},{"type":"p","text":"Now that you have your menu sorted and you’ve done outreach to compile a list of potential clients, your restaurant is ready to launch its new catering venture. Its an exciting time for everyone, but also a stressful balance between your old duties and this a new branch of food service."},{"type":"p","text":"Fortunately, recent developments in restaurant technology have made it easier than ever to keep track of your sales and handle all of your business operations, both in the restaurant and at catered events all localized in one network. At eatOS, our Point of Sale is designed to help with organization, inter-team communication, time tracking, ordering and secure transactions every time. Schedule a demo today to learn how we can help get your new catering venture off the ground and into the hearts and stomachs of your new clientele."},{"type":"p","text":"#eatOS #FoodService #OffPremiseDining #Restaurants #Catering"}]', 'https://static.wixstatic.com/media/a77ed6_732ad41e925e4922a826aaa851427e6d~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2022-09-16', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('streamline-your-delivery-order-preparation', 'Streamline Your Delivery Order Preparation', 'With COVID-19 forcing longer extensions of mass isolation measures, customers have turned to online ordering more than ever before. Delivery is an extremely popular method for getting groceries and food without facing...', '[{"type":"p","text":"With COVID-19 forcing longer extensions of mass isolation measures, customers have turned to online ordering more than ever before. Delivery is an extremely popular method for getting groceries and food without facing potential infection outside."},{"type":"p","text":"Now more than ever, making your delivery preparations as quick and efficient as possible is a necessity, both to meet the growing demand for that service and to make up for the significant profit reduction most restaurants feel from losing dine-in services."},{"type":"p","text":"Here are some tips for optimizing your restaurants’ system for delivery:"},{"type":"h2","text":"Use a Third Party Delivery Service"},{"type":"p","text":"Most of time, when a restaurant chooses to add delivery to its dine-in and pick-up services, they want to launch their own online ordering system so customers buy directly from them. This drives traffic on their website and avoids any potential fees that come from partnering with a third party."},{"type":"p","text":"However, putting your restaurant on a third party platform has advantages too. By using services like Postmates and Uber Eats, or any one of the myriad of options out there, you significantly cut start-up costs by reducing the time and energy spent building brand awareness. Instead, you immediately get the benefits of demand; with platforms like these, your target audience comes built in. Thus you don’t have to invest as much in advertising because these services market themselves, though you should still have an online and social media marketing campaign strategy to reach users who don’t use these apps. It’s also easier and faster to use one of these platforms than to design your own website or even modify your existing one, both of which cost time and money."},{"type":"h2","text":"Create a New Delivery Menu"},{"type":"p","text":"Designing a menu specifically tailored for delivery will ease your cooks’ workload and improve customer satisfaction. Despite the time and effort spent designing the perfect menu to epitomize your restaurant, not every signature dish will travel well to customers’ homes. No matter the reason, poor food quality can have a negative impact on your reputation and even lead to bad reviews online. Consider creating a delivery-only menu borne from variations of what you normally offer, prioritizing items that travel well and potentially even need less complicated prep. This will help cooks fill orders faster which in turns gets the meal out to the delivery driver more quickly. Customers appreciate short waiting times, which gives you an edge over your competition."},{"type":"p","text":"With COVID-19 forcing restaurants to shut down their most profitable services, you can temporarily do away with your regular menu entirely and retrain your kitchen staff to optimize the delivery process. For example, have one cook focus on making pizza and another handle all of the packaging, who can also hand food off to drivers. This will require a shift of responsibilities amongst staff but will ultimately ensure that each one gets more efficient at their individual tasks. Delegating specific tasks to specific employees also reduces human contact between staff members to avoid the potential spread of germs."},{"type":"h2","text":"Cook in Bulk"},{"type":"p","text":"Kitchen staff might spend a lot of time making the same order again, and again, and again especially with your more popular dishes. Rather than repeatedly making individual portions of the same dish, they can cut time out of the process by making larger batches and divvying it up into separate to-go containers. This cuts down on preliminary prep time and packaging, as cooks don’t need to create the same order multiple times or store food separately."},{"type":"p","text":"If delivery has you really busy nowadays, they could also cook items that keep well early in the day so that chefs don’t need to spend time on those dishes during busier hours."},{"type":"h2","text":"Develop a consistent prep time"},{"type":"p","text":"This takes practice. Once a cook works for you long enough, they’ll grow familiar with the menu and will have made each dish enough times to know the swiftest and most efficient way to prepare it. Knowing how long a meal will take allows you to give an accurate estimate to customers about when their order will arrive. This strengthens customer satisfaction, and also reduces how long drivers must wait before they can pick up an order, allowing them to optimize their time as well."},{"type":"p","text":"Overall, understanding how long a dish takes to make lets workers and customers plan accordingly, hastens the process and makes it easier on everyone."},{"type":"p","text":"With demand for delivery rising, now’s the time to experiment with better efficiency."}]', 'https://static.wixstatic.com/media/a77ed6_f31502aa9715480ebebc1121b10b224e~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-09-14', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('the-best-new-restaurant-technologies-in-2022', 'The Best New Restaurant Technologies in 2022', 'According to surveys, the restaurant industry isn’t always the front runner when upgrading its systems to meet new technology demands. The recent world’s health crisis and its economic effects helped them consider the...', '[{"type":"p","text":"According to surveys, the restaurant industry isn’t always the front runner when upgrading its systems to meet new technology demands. The recent world’s health crisis and its economic effects helped them consider the importance of meeting advanced technology trends. Furthermore, the most crucial lesson the pandemic has taught the business sector is how to survive and become more creative and innovative."},{"type":"p","text":"A study shows that by 2027, the food technology market will be valued at nearly USD 342 billion as the demand for advanced technology implementation continues to rise. Here are five restaurant technologies to help your food business be more efficient, cost-effective and survive in a post-pandemic era."},{"type":"ul","items":["Contactless payments-Aside from online ordering, customers can fully enjoy the art of digitization through contactless payment. Along with other features, it enables diners and the crew to continue their transactions with a lower risk of getting infected as covid 19 is still around the corner. Apart from that, it also provides a fast and easy cashless payment method everybody loves. And above all, for security, less cash inside the store means lower risks of getting robbed."]},{"type":"ul","items":["QR Codes- By 2025, QR code payments are predicted to grow by up to 240%.From its first use in 1994 to keep track of car parts, the invention of Japanese engineers has changed the face of technology worldwide. Still, the pandemic played a crucial role in increasing QR code usage. Moreover, a QR code provides restaurants with more information on their customers. More likely helpful in making a reservation. Furthermore, QR codes make it easier for the servers, managers and owners to meet all their regular and new customers’ needs."]},{"type":"ul","items":["AI- In major countries and cities worldwide, Automated Inventory and artificial intelligence are widely used. “Automated inventory increases restaurants’ bottom lines by closing the loop on food and beverages orders, inventories and food waste.” It allows food business owners to navigate new business techniques with fewer human interactions. AI has changed many restaurants’ traditional ways of interacting with their guests, improving customer experiences and aiming for work efficiencies."]},{"type":"ul","items":["Digital Kitchen & Menu Boards- It’s time to modernize the kitchen and connect the KDS or Kitchen Display System directly to the point of sale, kiosk, or online ordering. It will help simplify the ordering process to give a better dining experience to your customers. You can also view real-time analytics on preparation times, cancellations, wastage and more. It will allow you to make better decisions and run the kitchen more efficiently and profitably."]},{"type":"p","text":"Reviews and high-tech feedback-Online reviews are crucial in building your restaurant’s reputation and capturing your target market. It has always been essential in growing your business, as not everyone has the chance to visit your restaurant instantly. Many will read the review first and decide whether to come or not. In addition, it remains a laurel to communicate with their existing clients. On the other hand, the high-tech feedback system enables the owner and operators to establish relationships with their customers. Collecting immediate feedback through the digital ordering platform enables restaurant owners to gather reactions, respond to inquiries and provide real-time answers."}]', 'https://static.wixstatic.com/media/35ab20_7743e602c0754603a043a7f7673ed86b~mv2.png', 'Restaurant Growth', 'eatOS Staff', '2022-09-13', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('the-future-of-food-after-covid-19', 'The Future of Food After COVID-19', 'Even as everyone finally assimilates life under COVID-19, many wonder what the world will look like once we come out the other side. Under quarantine, people have gotten used to the weeks of staying inside, of ordering...', '[{"type":"p","text":"Even as everyone finally assimilates life under COVID-19, many wonder what the world will look like once we come out the other side. Under quarantine, people have gotten used to the weeks of staying inside, of ordering delivery and rarely going grocery shopping, and only getting the essentials when they do."},{"type":"p","text":"After the worst of this virus passes and we all re-emerge, some of our new practices will stay with us, both out of habit and simply because of society’s shifting priorities and newfound importance placed on hygiene."},{"type":"p","text":"What will the future of foodservice look like moving forward?"},{"type":"p","text":"1. Delivery will remain popular."},{"type":"p","text":"Now that people have gotten a taste for the joys and benefits of food delivery, it will likely remain a more popular method for getting dinner than it was before. More restaurants than ever now offer their food for pickup and delivery, including fine dining establishments that previously never even thought about which takeout container would keep their food fresh during travel. Many eateries have established these revenue streams and learned how best to take advantage of them; they’re unlikely to give that up after these self-isolation measures lift."},{"type":"p","text":"1. Support for local restaurants will continue to grow."},{"type":"p","text":"More than ever before, we’re all understanding the true value of community. People like the convenience, speed, and efficiency of fast food but the closures of so many treasured local businesses have shined a light on how truly thin a typical restaurant’s profit margins are. Communities have begun to rally around these small businesses to support them through this pandemic and are considering public good, as well as money and time when ordering their food. In all likelihood, this trend will continue after quarantines end as community members keep looking out for each other."},{"type":"p","text":"1. Prioritization of health and safety."},{"type":"p","text":"Though health and cleanliness have always mattered to the foodservice industry, they’ve never experienced such a high level of scrutiny and effort. The extent of the measures we take might decrease (for example, face masks probably won’t become the next fashion trend) but certain practices will remain the norm, such as increased hand-washing using proper technique, wet wipes for service jobs where employees come in contact with many different customers and more people carrying hand sanitizer on them in public."},{"type":"p","text":"People will also expect restaurants and other businesses to have sanitizer readily available by the door as they currently do. Some might even self-sanitize communal spaces before they sit there. Food safety, and health in general, will remain a big priority for society after COVID-19 ends in a bid to prevent something like this from ever happening again."},{"type":"p","text":"1. Curbside pickup and creative no-contact options."},{"type":"p","text":"With the rise in delivery and invention of new safety precautions, people have gotten used to contact-free methods of getting their food and groceries. Widespread implementation of curbside pickup, leave-at-your-door delivery options, discounts for pickup orders and other creative solutions have reduced too much face-to-face contact between kitchen staff, delivery workers and customers. These trends will probably continue to integrate themselves into the fabric of the foodservice industry."},{"type":"p","text":"1. Touch-free technology will become the norm."},{"type":"p","text":"As restaurants work to reduce face-to-face contact during takeout and delivery, they’re also strengthening safety protocols for dine-in customers for when normal life resumes. Touch-free apps and other such self-service technology will help reduce physical contact between customers and cashiers or waitstaff."},{"type":"p","text":"Touch-free apps allow customers to order from their phones while on the premises, just as they would do so online at home. This additionally shortens lines for the counter, cuts out the middleman and sends orders directly to the kitchen for preparation, and ultimately improves table turn time so you can serve more customers."},{"type":"p","text":"Other self-service technology such as kiosks, handheld devices that customers can use to order and pay directly from their table, and much more all contribute to increased profits and greater customer satisfaction. Of course, as we move into a post-COVID, more sanitized world, these communal devices will need frequent cleaning to ensure no germs are spread after each customers’ use. Even routinely wiping down these screens every couple of hours can significantly improve the overall health of your workplace."},{"type":"p","text":"Contact eatOS to learn more about what touch-free apps and self-service devices can do for your business."},{"type":"p","text":"Society’s approach to foodservice has already changed drastically in the few short months since the COVID-19 pandemic began. Our new way of thinking will not easily revert to how it was before. As we move forward after this virus, many of these new schools of thought that have led us to contactless pickup and delivery services, touch-free in-person ordering and more will likely be here to stay. It might even inform our approach to foodservice moving forward."},{"type":"p","text":"#CoronavirusPandemic #FoodService #HealthandWellness #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_11cac3dd9cc645a2b456cc83fdcfae54~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2022-09-08', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('the-second-wave-hits-texas', 'The Second Wave Hits Texas', 'In May, Texas became one of the first states to let their stay-at-home orders expire so nonessential businesses like restaurants could resume in-person transactions. For months, food service establishments have gone...', '[{"type":"p","text":"In May, Texas became one of the first states to let their stay-at-home orders expire so nonessential businesses like restaurants could resume in-person transactions. For months, food service establishments have gone without dine-in operations and stayed afloat only through takeout and delivery services, if they remained open at all."},{"type":"p","text":"Now, after a month and a half of businesses opening one by one and the general public readjusting to how life was before the COVID-19 pandemic hit U.S. soil, restaurants have to contend with a new possibility: That they’re experiencing the forewarned second wave, right as they’re getting used to full service again."},{"type":"h2","text":"How are restaurants operating now?"},{"type":"p","text":"Recently, Texas allowed restaurants to operate at 75% capacity and bars to open at 50% capacity. This accommodates more customers especially since restaurants can now space tables four feet apart instead of six, although officials recommend putting a partition or some other kind of barrier between neighboring tables."},{"type":"p","text":"These new, looser regulations are extremely beneficial for small businesses who often don’t have the physical space to accommodate 75% capacity while maintaining six feet of distance between customers. Nonetheless health experts recommend the six foot rule to avoid the spread of germs, and reducing the requirements presents a serious health concern: Even if Texas saw a steady decline in the number of confirmed COVID-19 cases over several weeks, which they haven’t, the six foot rule would still be necessary to keep people from getting sick. Safety regulations like that don’t positively correlate with lower COVID-19 cases; requisite distance doesn’t decrease just because case numbers do."},{"type":"p","text":"Perhaps not surprisingly, Texan health officials report that the general public has gotten more lax too; fewer people wear masks, social distance properly and take sanitation measures seriouslyeven simple precautions like frequent hand washing. On Friday, June 12th, Texas reported the highest number of new cases since the pandemic started, a grim finish for a week that broke the record for the most positive COVID-19 tests to date, too."},{"type":"p","text":"Steve Adler, mayor of Austin, TX sees a relation between relaxed safety precautions and the uptick in confirmed cases: We have a lot of people out there living their lives like the virus is over. It would be less of a concern if people were wearing face coverings and maintain that six-foot distancing."},{"type":"p","text":"Unfortunately, the Texas Restaurant Association doesn’t believe that allowing more people to dine-in will solve restaurants’ financial troubles like they hope, which means they’re risking exposure for nothing: The TRA predicts the ongoing pandemic will ultimately cause 25-30% of restaurants to close permanently. Even those that have stayed afloat by taking advantage of pickup and delivery services, or by implementing other creative revenue streams, have had to shut down when the months of struggle finally took their toll. It doesn’t look like limited capacity is enough to offset the public’s ongoing fear of the virus."},{"type":"h2","text":"How can restaurants control the spread?"},{"type":"p","text":"Austin, TX and surrounding areas have reached Stage 4 of the public risk chart, basically meaning that they have a moving average of more than twenty new hospitalizations each week."},{"type":"p","text":"As a result, the city reiterated its safety recommendations in the hopes that people take the pandemic more seriously again, despite increasing restlessness causing people to break self-quarantine. They recommend that people pay more attention to personal hygiene, that they stay home if they’re sick or displaying any symptoms, and that they avoid anyone who has tested positive for the virus. Health officials also urge continued social distancing and for everyone to cover their faces when they go out in public; despite state and local regulations easing, experts strongly recommend avoiding any social gatherings, meeting with more than two people and doing any traveling that isn’t strictly essential."},{"type":"p","text":"In hopes of impressing this more seriously on the public, Mayor Adler sent out a letter over the weekend warning Austin residents of the impending surge in cases; advanced notice might suppress certain behaviors that could overwhelm hospitals in the coming weeks. He specifically indicated that restaurants reopening to greater capacity has and will continue to spread COVID-19, thus contributing to these impending hospital admissions. Nevertheless, there have been no policies passed to back the warnings."},{"type":"p","text":"On June 15th, Austin officials held a press conference to address the community’s concerns. They discussed new and revised protection orders alike, aimed at slowing hospitalization rates as well as further spread of the virus. They want to avoid overwhelming the healthcare system when the second wave hits in full force as it’s already, inevitably, begun to do."},{"type":"h2","text":"A new Texas moving forward"},{"type":"p","text":"Small businesses experienced COVID-19 outbreaks on a small scale, when staff and customers tested positive just a few weeks after doors reopened. However some affected restaurants and bars around Austin only closed for two days, not weeks like health experts recommend. When the second wave hits in full force, they might find themselves blocked from hasty reopening by legal policies put in place."},{"type":"p","text":"Other states should take note, particularly ones that reopened early like Texas did or who are experiencing similarly record-breaking caseloads as the second wave rolls in a few weeks after reopening nonessential businesses, right as the incubation period ends. States like Georgia, Arizona and Arkansas need to start trying to avoid overburdening their healthcare systems, too. Although preemptive action can’t control the amount of people who have surely been affected already in the month and a half since nonessential businesses reopened, it can prevent an even greater number of cases from pouring in over upcoming weeks."},{"type":"p","text":"Even states that have remained diligent throughout the pandemic should beware reopening the economy before meeting federal health standards. Make sure to have a steady downturn in new cases, control the spread and see fewer deaths before taking measures that will not only endanger citizens’ health but also necessitate a resurgence in stringent quarantine measures, effectively resetting the clock on three months of hard work."},{"type":"p","text":"Dear fellow Americans: Buckle in for a long, sheltered summer. It’s time to flatten the curve once again."},{"type":"p","text":"#Community #Covid19Pandemic #FoodService #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_ac50222ac78b4c778c16624c548d94ed~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-09-07', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('what-goes-into-a-restaurant-survey', 'What Goes into a Restaurant Survey?', 'Skip to Main Content', '[{"type":"p","text":"Skip to Main Content"},{"type":"p","text":"Customer surveys are a good way to find out more about guest preferences straight from the source. This gives you a better starting point when it comes to marketing ideas and creating promotions. Here’s everything you need to know about making a smarter restaurant survey."},{"type":"p","text":"Celpax on Unsplash"},{"type":"h2","text":"Tools for Success"},{"type":"h2","text":"What Kind of Questions Should You Ask?"},{"type":"p","text":"What you’re asking customers matters just as much as how you ask it. Remember, you already provided the service that guests are paying for so they’re completing this questionnaire on their own time. Keep it short, sweet and to the point to prevent people from clicking away before they finish. The ideal restaurant survey has fewer than five questions that take no more than ten minutes to complete."},{"type":"p","text":"1. Mix open-ended with multiple choice so they don’t feel overwhelmed and you still get a bit of detail."},{"type":"p","text":"2. Ask one question at a time. For example, split up, “What did you like best about your meal? What did you like the least about it?” into two separate questions or simplify it to say, “How was your meal?”"},{"type":"p","text":"3. Instead of asking why guests liked or disliked something about the service, ask what they experienced. This helps you avoid leading questions and eliminates bias from the survey."},{"type":"p","text":"Mostly, just remember simplicity is best. You don’t have to use every question that comes to mind. Keep the survey short and quick. You can even rotate questions throughout the year to aggregate more data without overwhelming customers."},{"type":"h2","text":"Is Your Survey Ready for Launch?"},{"type":"p","text":"Once you’ve built a survey that you’re sure will give you the most necessary data, it’s time to have others give it a second look. Test your survey on different devices to make sure it’s equally optimized for mobile, desktop, and tablets. Also, have your staff test it out to double-check that the questions make sense, are easy to answer, and that they would actually follow through with the whole survey if they were a customer."},{"type":"p","text":"Response rates are higher when you run your questionnaire through employees first. You should also swap out your survey questions semi-regularly so your best customers have room to change their opinions. This also gives you a chance to learn about various aspects of the business, not just answers to those same five recycled questions."},{"type":"h2","text":"Survey Question Examples"},{"type":"p","text":"Coming up with relevant queries can be difficult, but here are a few ideas to get you started with brainstorming."},{"type":"p","text":"1. How likely are you to recommend us to a friend?"},{"type":"p","text":"2. Was the service quick enough today?"},{"type":"p","text":"3. What do you want to see on the menu that isn’t currently there?"},{"type":"p","text":"4. How often do you visit us?"},{"type":"p","text":"5. What did you like most about your experience?"},{"type":"p","text":"6. What did you like least about your experience?"},{"type":"p","text":"7. How was your service today?"},{"type":"p","text":"8. Rate our cleanliness on a scale of 1-10."},{"type":"p","text":"9. Would you eat here again? Why or why not?"},{"type":"p","text":"Remember that these are only suggestions. Use them as a jumping-off point to generate ideas that apply specifically to your service and your customers."},{"type":"p","text":"A good restaurant survey identifies weak and strong points of the business so you can do better in the future. Critiques are necessary and asking your best customers to point out what you’re doing wrong will help you grow. It’s all about becoming a better business so you can make every sit-down meal a positive experience. Sometimes restaurants just need a smarter Point of Sale to manage their employees and customers more effectively while streamlining operations too."},{"type":"p","text":"#CustomerFeedback #eatOS"}]', 'https://static.wixstatic.com/media/a77ed6_433f471fb4c841bdaa86c6708fcb0a37~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2022-09-02', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('what-s-the-fixation-on-prix-fixe', 'What’s the Fixation on Prix Fixe?', 'Depending on what type of restaurant you run, you have a myriad of options when it comes to menu creation and management. In more upscale establishments, customers might find something called a prix fixe menu. However,...', '[{"type":"p","text":"Depending on what type of restaurant you run, you have a myriad of options when it comes to menu creation and management. In more upscale establishments, customers might find something called a prix fixe menu. However, a restaurant doesn’t have to be fancy to do it: Any full-service restaurant can offer a fixed price menu to their guests, and there are tangible benefits for those that do."},{"type":"h2","text":"What is Prix Fixe?"},{"type":"p","text":"Prix fixe menus refer to offering multiple courses for a set price. It allows minimal customization by guests and much less work for your kitchen staff, although some restaurants give customers a choice between a couple of different prix fixe meals."},{"type":"p","text":"Although the practice is generally limited to fine dining, there’s still variety in how and when to offer prix fixe meals, which leave restaurateurs with options about what suits their business needs best."},{"type":"p","text":"1. Daily prix fixe rotates the menus each day. It’s an excellent way to incorporate variety, upsell particular specials, or for upscale places to convince customers who can’t usually afford to splurge to get more bang for their buck."},{"type":"p","text":"2. Special occasions warrant special menus, particularly during holidays like Valentine’s Day, Mother’s Day, or entirely long weekends and restaurant industry events."},{"type":"p","text":"3. Tasting menus are filled with a lot of small plate courses so guests can try a little bit of everything you’ve got up your sleeve."},{"type":"p","text":"Prix fixe menus certainly aren’t right for every restaurant, and they’re not going to be suitable for every customer either. Identifying your target audience and your core, most loyal customers can be an asset in this momentous decision about whether to overhaul your menu or add a few prix fixe courses to your specials deals."},{"type":"h2","text":"Pros of Prix Fixe Menus"},{"type":"p","text":"There is such a thing as too much free will. Studies show that presenting too many options makes it difficult for customers actually to settle on a dish. With prix fixe, the courses are decided for them so they can focus on enjoying time with friends or family. A better time out leaves them with a better impression of their experience with you overall."},{"type":"p","text":"Your kitchen staff will appreciate having some of the load off their shoulders, too, especially during busy holiday seasons. Cook dishes in bulk when chefs already know what everyone’s going to order; this prevents too many ingredients going to waste and avoids a bottleneck during peak times when they’re trying to get meals out quickly. Operations run smoother without the guesswork, human error in inputting orders, and exaggerated wait times."},{"type":"p","text":"All of this adds up to greater profits for you. If you price your menu right, ultimately, the customers get more food for their money while your ticket average increases because they’re purchasing courses that they might not have ordered on their own. Do the math right, and everybody wins."},{"type":"h2","text":"How to Make a Good Prix Fixe Menu"},{"type":"p","text":"So you know that prix fixe would be a good idea, whether you want to offer one full time or only on special occasions, and if your customers would enjoy it like you think they will. Now it’s time to actually create a full prix fixe menu that fits your brand and will be as lucrative as you expect."},{"type":"p","text":"First, decide how many courses to offer and if you’re going to give customers any choice; some restaurants offer several dishes in each section for customers to choose from. If you do this, make sure that the menu is cohesive; appetizers and desserts make sense with each entree so every customer is guaranteed a great experience no matter what dishes they choose."},{"type":"p","text":"Make smarter business decisions with advanced Point of Sale devices that have automatic reporting capabilities: You’ll see your most popular dishes and lowest-cost ingredients, as well as other critical sales data that will help you save and earn money. Building these into the menu not only ensures that your guests are happy with the options available to them, but your profit margins will be higher too. In-season ingredients, pasta, and vegetarian options are all great jumping-off points when creating your prix fixe menu."},{"type":"p","text":"Now you know what prix fixe is and how to build your very own specialized menu that caters to your best customers, restaurant’s theme, employee optimization, and overall business operations. If you’re a full service restaurant looking to build your own to replace your current menu or simply add to it, why not start now?"},{"type":"p","text":"At eatOS, we’ve developed cutting-edge Point of Sale technology and associated devices to help with menu management, sales reports, and more. Get a better understanding of how your business is doing and make smarter decisions as a result. Book a demo with eatOS today, and together, we’ll bring your restaurant into the future of foodservice."},{"type":"p","text":"#eatOS #MenuDesign #Restaurant #RestaurantBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_299be3706e6244cbb04b5a66359cb801~mv2.jpeg', 'Kitchen Operations', 'eatOS Staff', '2022-08-31', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('why-are-restaurants-opening-their-kitchens', 'Why Are Restaurants Opening Their Kitchens?', 'Restaurants must constantly innovate to stand out in a market saturated with potential places to dine out. Customer expectations shift frequently and trends constantly change, and businesses must remain flexible enough...', '[{"type":"p","text":"Restaurants must constantly innovate to stand out in a market saturated with potential places to dine out. Customer expectations shift frequently and trends constantly change, and businesses must remain flexible enough to meet those needs. As people grow more curious about what goes into their food, some restaurants have adapted to this interest by adopting an open kitchen design."},{"type":"h2","text":"What is an open kitchen?"},{"type":"p","text":"In these restaurants, cooks prepare food in plain sight of customers. Although this can take many different forms, venues like Subway, Chipotle and Blaze Pizza probably come to mind first. True, these are one form of open kitchens, where the ingredients are laid out behind glass and customers can choose ingredients from the containers they see. However, other types also exist."},{"type":"p","text":"Open kitchen designs refer to any layout where customers can see their meals being prepared. This can mean chefs cooking near the tables at sit-down restaurants, windows or glass walls allowing customers to see directly into the kitchen, or that more easily recognizable Subway-style design. Although open kitchens are more popular with, and more conducive to, fast casual restaurants, the trend has been adopted by many businesses including fine dining establishments. However you may wonder if this model really benefits the business or if it’s just another trend."},{"type":"h2","text":"Transparency"},{"type":"p","text":"By nature, open kitchens promote transparency between the business and its customers. When they can see everything that traditionally goes on behind closed doors, customers can verify for themselves that your kitchen follows proper health and sanitation guidelines. This assuages any safety concerns that they might have. One example of a business implementing open kitchens to combat these very fears is Dominos, who in 2015 first introduced “Pizza Theater.”"},{"type":"p","text":"Pizza Theater is exactly like every other open kitchen concept, only with a brand-specific name. Renaming the layout choice personalizes the experience for Dominos customers and fosters brand recognition. Workers make and cook pizzas behind a glass pane so customers can watch them prepare the entire order right in front of the lobby, which also has the chance to draw in people simply walking by outside. Initially, Dominos made the change to combat rumors of uncleanliness in a way that provided an easy solution to these concerns. However they ultimately gained from it in more ways than one."},{"type":"p","text":"Transparency also has the added benefit that customers can see and smell their food being made. Not only does this make them hungrier but also, in places that do employ an open layout the way that Subway does, lets customers make better informed decisions about what ingredients they want in their food."},{"type":"h2","text":"Entertainment"},{"type":"p","text":"This design also adds a flair to your restaurant that many eating establishments just don’t have, giving you an edge over your competition. Every successful restaurant has some niche that they fill that other places can’t, some specific demographic they’re reaching with its concept, design and atmosphere."},{"type":"p","text":"Thanks to celebrity chefs and the popularity of cookings shows, more people than ever are interested in what goes on in restaurant kitchens and how their favorite dishes get made. Open kitchens are a fun, interesting draw to bring in customers and can be exactly what your restaurant needs to stand out."},{"type":"h2","text":"Going green"},{"type":"p","text":"On top of the potential benefits to your business, open kitchen designs also improve the environment. Fewer rooms means reduced energy use; you don’t need to spend as much on heating, cooling or lighting separate areas. This model promotes better ventilation for the restaurant too. All of this saves you money and helps the planet simultaneously."},{"type":"p","text":"A TGI Friday’s in Nashville considered the environmental impact a vastly important factor. After a flood ravaged the restaurant in 2010, they took two years to rebuild. When they reopened in 2012, they chose to capitalize on open kitchens because they wanted to reduce their energy use and support the planet."},{"type":"h2","text":"Are open kitchens better?"},{"type":"p","text":"They certainly benefit some restaurants, but the upsides they provide aren’t universal. Rather, open kitchens are one model to consider, but the right decision depends on your business operations, demographics and the atmosphere that you want to cultivate. Open kitchen designs have their downsides just like any other layout."},{"type":"p","text":"Messy kitchens are natural and expected to some extent, especially during peak times when cooks get very busy and need to produce a lot of food in a short amount of time. However justifiable, perceived uncleanliness or disorganization could negatively impact customers’ views of your establishment. Watchful customers also means that kitchen staff has less room to make mistakes and more difficulty making up for them when they do, so this model could put undue strain on your workers."},{"type":"p","text":"Whirring equipment, cooking food, banging pots and pans, and staff talking to each other all tend to make kitchens very loud as well. If you envision your restaurant as a calm, quiet place for customers to relax and enjoy themselves or a conversation, this design might hinder you more than it helps. Similarly, if you have another focal point in your restaurant that makes you stand out from competition, like live music, an open kitchen could distract from that and ultimately hurt your business."},{"type":"p","text":"Some restaurants thrive with closed kitchens; others benefit enormously from giving customers a look behind the scenes. There’s no one, perfect way to design your restaurant. If you want to establish an atmosphere of transparency and allow customers to see all the interesting work that goes on in the back of the house, then open kitchen designs can be greatly beneficial, both for your customers’ peace of mind and for your bottom line. By weighing the pros and cons, you can make a more informed choice and set your restaurant up for success."},{"type":"p","text":"#Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_2878858f17e7428dad4706a11d08ec8d~mv2.jpeg', 'Kitchen Operations', 'eatOS Staff', '2022-08-30', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('a-z-terms-for-every-restaurant-s-back-of-house', 'A-Z Terms for Every Restaurant’s Back of House', 'When you work in a commercial kitchen, there’s so much on your plate both literally and figuratively that it can be challenging to keep all the lingo straight. Often, and especially when it’s busy, your coworkers in the...', '[{"type":"p","text":"When you work in a commercial kitchen, there’s so much on your plate both literally and figuratively that it can be challenging to keep all the lingo straight. Often, and especially when it’s busy, your coworkers in the back of the house or servers trying to juggle tables out on the floor will write shorthand on their tickets or call out slang terminology to the cooks."},{"type":"p","text":"It’s essential to know some basic culinary terms if you’re going to pursue a career in a fast-paced restaurant kitchen, whether you go into fine dining or stay in the back of QSRs. Here are 26 terms you should familiarize yourself with to excel at your job."},{"type":"p","text":"01. Al dente: You’ve heard of cooking steaks medium to rare, but al dente refers most often to cooking _pasta_ so it’s firm, although you can say this about any food."},{"type":"p","text":"02. Baste: Prevent food from getting too dry as it’s cooked to perfected by pouring or rubbing juice and fats over meats while they’re cooking"},{"type":"p","text":"03. Chop: Cut up an ingredient, usually vegetables, into big but usable pieces."},{"type":"p","text":"04. Dice: Cut up an ingredient into smaller pieces about a quarter to an eighth of an inch."},{"type":"p","text":"05. Emincer: Cut up an ingredient into thin slices, but not as long as julienne cuts."},{"type":"p","text":"06. Filet: Debone meat or fish before serving it."},{"type":"p","text":"07. Galette: Flat, round pastries that are usually topped with fruit or some other food in a similar style."},{"type":"p","text":"08. Halloumi: A kind of cheese made from goat or sheep’s milk, sometimes a combination of the two, and can also include traditional cow’s milk. It’s unripened, brined, and slightly salty."},{"type":"p","text":"09. Infused: Cooks extract flavors or chemicals from a vegetable, water, oil, or alcohol, so a particular ingredient steeps in it and gets all that flavor."},{"type":"p","text":"10. Julienne: Cut up an ingredient into short, thin strips."},{"type":"p","text":"11. Knead: Work dough into a cohesive mixture by stretching, massaging, and folding it."},{"type":"p","text":"12. Larding: The act of putting fat into meat so it will melt and prevent the meat from drying as it’s cooked."},{"type":"p","text":"13. Marinate: Soak foods in a seasoned liquid before cooking to add those flavors to the dish."},{"type":"p","text":"14. Needle: Inject fat or flavors into food to make its taste more powerful."},{"type":"p","text":"15. Ort: The food left on a plate once guests leave at the end of a meal, which can be composted."},{"type":"p","text":"16. Parcook: To lightly cook food, but not fully, so that someone can finish it when it’s ready to be served."},{"type":"p","text":"17. Quadriller: Criss-cross lines on the surface of food, as with a fork, as part of your overall presentation."},{"type":"p","text":"18. Render: Meltdown and cook out the fat from something by simmering it over medium heat."},{"type":"p","text":"19. Sauté: Cook food quickly over high heat. This technique is named after the way food “jumps” in a hot span."},{"type":"p","text":"20. Temper: Add hot or boiling liquid to a food a little bit at a time to slowly raise its temperature."},{"type":"p","text":"21. Unleavened: Usually referring to bread, this means that it’s been made without yeast or any other ingredient that causes it to rise."},{"type":"p","text":"22. Vol-au-vent: A pastry that’s baked and then filled with meat or vegetables."},{"type":"p","text":"23. Whip: To beat an ingredient or mixture until it has air and volume, typically with a whisk or mixer."},{"type":"p","text":"24. Xanthan gum: A common food additive used to thicken salad dressings. It’s produced by fermenting sugar."},{"type":"p","text":"25. Yakitori: A Japanese term for food that’s been marinated in sauce, grilled and skewered."},{"type":"p","text":"26. Zest: Scrape or grate the skin of the fruit to add flavor to a dish."},{"type":"p","text":"It can be hard to learn the ins and outs of a new kitchen, memorize the specific duties that come with a new job, and keep all of the relevant terms straight in your head. The restaurant industry is saturated in specific lingo and terminology that any cook can pick up, but they’ll need to study hard to keep it all straight."},{"type":"p","text":"Make your new job a successful one. This A-Z list of twenty-six simple culinary terms to memorize will help you start your new restaurant career knowledgeable and ready."},{"type":"p","text":"#CommercialKitchen #eatOS #RestaurantBusiness #FoodService #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_77af23e375944e0983457201f79afe65~mv2.jpg', 'Kitchen Operations', 'eatOS Staff', '2022-08-25', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('are-you-doing-inventory-wrong', 'Are You Doing Inventory Wrong?', 'The way you do inventory matters. It doesn’t just show how well your business is doing, but also determines the price of each dish. It’s a thin line between competitive pricing and losing money, especially in the...', '[{"type":"p","text":"The way you do inventory matters. It doesn’t just show how well your business is doing, but also determines the price of each dish. It’s a thin line between competitive pricing and losing money, especially in the restaurant industry. Inventory affects how you calculate the cost of goods sold, which informs how much you need to sell each dish for to make a profit. Learn more about calculating COGS."},{"type":"p","text":"Photo by Karolina Grabowska from Pexels"},{"type":"p","text":"You’ll know something is off with your inventory if it varies too much from week to week. Your sales numbers and usage should match up, so fluctuations are a strong indicator that something’s wrong. Doing inventory correctly affects everything else about the way you do business."},{"type":"h2","text":"Inventory Turns"},{"type":"p","text":"How do you really know how much product you’re selling, especially when you restock throughout the week to keep sales moving? That’s why business owners need to familiarize themselves with inventory turns. These measure how often you run out of all your ingredients and restock the shelves."},{"type":"p","text":"Find inventory turns by adding your beginning and ending inventory together, then dividing by two. Next, divide your usage by your average inventory and there you’ll find your inventory turns."},{"type":"p","text":"Make sure the number is accurate by then checking how many deliveries you received from vendors during that time period. This has to match up with your inventory turns; it’s physically impossible to empty your shelves three times but only get deliveries twice. Therefore by finding both these numbers, you can assess how well the business is doing and if your calculations need readjustment. If your inventory turns don’t align with how many deliveries you received during that period, you could be losing money somewhere along the way."},{"type":"h2","text":"Lower Food Costs"},{"type":"p","text":"Taking a smarter approach to inventory management also minimizes one of your biggest expenses: Food costs. Why keep potential sales on the shelves? More inventory turns per period mean more profit for that time period too, increasing your total sales per dish relative to what you paid to make it (also known as ideal food cost percentage)."},{"type":"p","text":"As ingredients linger on the shelves, the likelihood of employee theft or food simply going bad also goes up. Essentially, your efficiency depends on how well you move product. Consistency results in lower food costs to support profit growth in your restaurant."},{"type":"h2","text":"Inventory and Your Budget"},{"type":"p","text":"How you do inventory affects every aspect of business. Get a more accurate budget when you properly calculate how much business you do in a given time period. When you identify areas of overspending, you can adjust how much to order or increase menu prices accordingly."},{"type":"p","text":"Streamlining your budget and more efficiently managing inventory results in less theft and food spoiling on the shelves. This means more money in your pocket at the end of the day; food waste accounts for a lot of your unnecessary expenses. When you upgrade your restaurant technology to include Point of Sale systems that can handle a lot of these calculations automatically, you’ll perform less manual labor, free up time to focus on more pressing tasks in the restaurant, and save money with a faster-generated, more accurate budget."},{"type":"p","text":"NORTHFOLK on Unsplash"},{"type":"p","text":"Take inventory a better way to lower food costs and get a more accurate vision of each week’s profits with a smart Point of Sale."}]', 'https://static.wixstatic.com/media/a77ed6_f8fff03268c242249a8e742ca06d02f4~mv2.jpg', 'Inventory Management', 'eatOS Staff', '2022-08-24', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('are-you-tracking-your-employee-breaks', 'Are You Tracking Your Employee Breaks?', 'Your employees are the face and heart of your restaurant, which is why it’s so important to cultivate an atmosphere where they can work their hardest and do their best every single day. Though rest periods may seem...', '[{"type":"p","text":"Your employees are the face and heart of your restaurant, which is why it’s so important to cultivate an atmosphere where they can work their hardest and do their best every single day. Though rest periods may seem counterintuitive to productivity, ensuring that your staff gets the recommended amount of breaks per shift is actually integral to a smooth operation. Ensure and track employee breaks with crucial employee management software that improves any businesss success."},{"type":"p","text":"According to state and federal laws, mandates surrounding employee breaks separate them from allotted food time. Meals are usually thirty minutes long, completely absolve the employee from any potential duties during that time, and aren’t paid or counted toward total hours worked, including overtime. Meanwhile breaks typically last between 5 to 20 minutes and are considered compensated work hours that account for part of their timecard."},{"type":"p","text":"Federal laws don’t _require_ that restaurants give their employees a break, but they do have regulations in place for restaurants that choose to allot time off."},{"type":"h2","text":"What good are breaks?"},{"type":"p","text":"Long periods of work without respite causes stress and exhaustion. Giving employees a chance to rest during long shifts actually improves their productivity. A rest, even a short one, boosts their mood and gives them a chance to recharge before the rest of the day. It ultimately improves decision-making and motivation as well as creativity, all of which provides a much-needed second wind that keeps productivity high."},{"type":"p","text":"Everyone needs the time and space to mentally recharge before tackling the second half of a long day. In short, breaks are necessary, so learn how to allocate them appropriately to maximize efficiency throughout the day."},{"type":"h2","text":"When should staff take breaks?"},{"type":"p","text":"When, how and where employees take their breaks is pretty much up to you. For example, if you don’t let staff members on their phones during work, consider allowing it during break time; if people take the opportunity to smoke, designate how far away from the building they should stand or create a specific smoking area. Decide if you want anyone, or certain employees, to take breaks together. Can they get free or discounted meals during that time? That will affect your taxes but potentially improve morale."},{"type":"p","text":"Time tracking and advanced restaurant analytics are a great resource to use when determining employee break times. If you review sales data by day, hour and even employee then you can determine peak times and plan breaks around that, or at least make sure you have appropriate coverage for a rush. Alternatively, you might want to schedule more breaks during low traffic hours, or strategically spread them out during normal busyness."},{"type":"h2","text":"How do you get staff on board?"},{"type":"p","text":"The key to a happy staff is communication and mutual respect. You may understand why you’re setting break times the way that you are, but it won’t help morale the way you might intend unless you communicate your expectations to everyone. Lay it out as early as the initial training sessions so theres no surprises whatsoever. Make sure employees know their rights too, as this fosters better trust between staff and management, which encourages everyone to work harder. Together you can make sure employees are taking all the time they need to recharge for a successful workday."},{"type":"h2","text":"How do you track breaks?"},{"type":"p","text":"The advancing restaurant technology industry focused on cultivating better employee management systems, so you can be sure that your team is working their hardest. Invest in devices with time tracking capabilities so as to monitor employees’ breaks and make sure they’re taking the time to recharge that everybody needs."},{"type":"p","text":"At eatOS, our advanced Point of Sale system makes it easy to track their times. Built-in employee management functions are designed to help you manage everything from schedules to breaks and more. Make better decisions about team management when you incorporate sales analytics, as well as integrated software and devices on the same network, into your decision-making process."},{"type":"p","text":"Employee management isn’t easy, but demonstrating that you prioritize their mental wellbeing by incorporating break times into the schedule is a great place to begin strengthening your relationship with the team and improving the overall efficiency of your operations. A happy team works harder, and everyone needs a rest now and again. Optimize your employees’ breaks with advanced Point of Sale technology and let eatOS track your employees’ times so they, and you, have a better workplace experience."},{"type":"p","text":"#eatOS #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_e82deefe6fa84741b4927b4912766ed0~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2022-08-19', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('can-cloud-kitchens-save-the-restaurant-industry', 'Can Cloud Kitchens Save the Restaurant Industry?', 'Cloud kitchens are also known as ghost kitchens have existed for a while, but with COVID-19 forcing a surge of quarantines and social distancing across the globe, they’re more popular than ever.', '[{"type":"p","text":"Cloud kitchens are also known as ghost kitchens have existed for a while, but with COVID-19 forcing a surge of quarantines and social distancing across the globe, they’re more popular than ever."},{"type":"h2","text":"What is a cloud kitchen?"},{"type":"p","text":"With a traditional cloud kitchen, you rent a space to operate your kitchen out of and only hire the staff necessary to run it. These “virtual restaurants” only offer delivery services with no option to dine-in or pick-up at all. They don’t need front-of-house staff because customers only have the option to order online."},{"type":"p","text":"Now that many, many cities around the world have shut down dine-in service in response to the COVID-19 pandemic, a lot of foodservice establishments effectively operate like cloud kitchens anyway. It’s an extremely good balance between social distancing and fulfilling consumers’ increased need for delivery now that they can’t go out to eat and, in some places, even leave the house except to buy necessities."},{"type":"h2","text":"How can we support this delivery-only service?"},{"type":"p","text":"With the right point-of-sale technology, online ordering is actually more efficient than ever. The best systems can send the orders directly to the kitchen’s display screen for immediate attention, no middle man required. Many restaurants implemented this technology before the pandemic, drawn to the benefits of seamlessly sending information across their restaurant in real-time. Now with isolation measures in place, this technology is even more crucial to keep up with the rising demand for delivery. With a lot of restaurants questioning if they’ll even stay open through the week, reducing labor costs (and human contact as well as the number of employees in one space) can critically boost your bottom line."},{"type":"p","text":"However, your menu might require a bit of reworking so it fits this model. Some dishes travel better than others, so you might have to create a temporary delivery-only menu (or expand the one you have) to maintain the integrity of your food and reputation. Temporarily integrating delivery pick-up zones, efficient but safe measures for passing orders to drivers, and waiting areas for drivers can all make cloud kitchens faster and more efficient. All of these protocols can be further developed (or tweaked, if you already have some of these systems in place) to reduce human contact and thus reduce the spread of germs. In times like these, every bit counts."},{"type":"h2","text":"How can my restaurant make the shift?"},{"type":"p","text":"If you didn’t offer delivery before the COVID-19 pandemic, first you’ll need to develop a method to actually get the food to your customers. Cloud kitchens rely on an internal system but may additionally outsource to a third party app."},{"type":"p","text":"Regardless of whether you use an app, you’ll need to hire drivers and come up with your own delivery pricing, including how you’d like to handle driver tips and how much to charge as a delivery fee."},{"type":"p","text":"If you use a third-party app, the added exposure will likely earn you a ton of new customers quickly, but these platforms can take a pretty hefty chunk of the profits per sale. With a plethora of apps to choose from, though, you can shop around to see which suits your business best (if any)."},{"type":"p","text":"You can also incorporate pick-up options into this cloud kitchen model. For pre-existing brick-and-mortar restaurants now going digital because of the pandemic, it’s especially easy to do so. Just designate awaiting and pick-up area for customers and let them come to you. This way also allows you to offer some of the dishes that you can’t deliver, which might include a signature or popular meal that just doesn’t travel too well so you don’t have to cut these options out completely."},{"type":"h2","text":"Why isn’t everyone doing this?"},{"type":"p","text":"Plenty of restaurants never had a need to before. If you’re operating from a brick-and-mortar location, you want to focus on dine-in service, and as a result delivery orders can fall to the wayside, especially during peak hours."},{"type":"p","text":"With dine-in services shut down in a lot of places, and social distancing the new norm across the globe now’s the time to pour all that energy into delivery. People still need to eat, and it might be the only thing keeping your business afloat until this pandemic blows overwhenever it finally does."},{"type":"h2","text":"How to run a virtual restaurant"},{"type":"p","text":"If you’ve closed the doors to dine-in, and you aren’t offering pickup, then for all intents and purposes you now run a virtual restaurant."},{"type":"p","text":"True virtual restaurants, also known as ghost restaurants, often have multiple businesses operating within the same premises, which maximizes the efficiency of the room. Many cloud kitchens also rent space to other brands to help turn a profit, although they already save money on rent because they don’t need floor space for dine-in customers and they don’t need to rent in a prime location; they can operate from wherever they want in their delivery area."},{"type":"p","text":"One major upside of a virtual restaurant is that you can optimize it for consumer demand and worry less about alienating customers. Operating without a physical location means higher adaptability, so you can adjust your menu seasonally, decrease food waste and operate at busier hours."},{"type":"h2","text":"The downsides of cloud kitchens"},{"type":"p","text":"Most of the personalized nature so critical to foodservice gets lost in delivery since the staff has no face-to-face time with customers, so satisfaction falls entirely on the speed and quality of the order. You also have to pay workers a livable wage because, aside from the driver, they don’t get any tips."},{"type":"p","text":"As mentioned above, third-party apps can also cause problems. They have very high fees to start with, not even accounting for the instances where a customer calls a restaurant but doesn’t order anything, but the app bills it as a sale anyway. You’re also handling your food over to an entirely different company, which puts your brand in the hands of workers who you don’t know and who probably don’t care much about your reputation. Although you do still have your own delivery system in place, you’ll have to pay more for marketing if you don’t use a third-party service."},{"type":"p","text":"Your cloud kitchen also relies entirely on online customers, so you have to pay for visibility to garner good reviews and positive word of mouth; there’s no foot traffic to increase sales."},{"type":"p","text":"There’s also food quality and safety to consider. If a dish doesn’t come just as appetizing as it would at a dine-in restaurant, no matter the reason, customers won’t buy from you again and might even post negative reviews which considering your business relies so heavily on positive reviews online can cause your reputation serious damage that, in some cases, you just can’t come back from."},{"type":"p","text":"With everyone staying inside to avoid spreading COVID-19, learning how to own and operate a cloud kitchen is a great way to keep your restaurant functioning as we all struggle to get through this difficult and confusing time. If you generate even a little bit of business, it might just tide you over until dine-in service is back up and running. And hey you might find out you’ve got a penchant for delivery and decide to go all-digital from now on."},{"type":"p","text":"#CoronavirusPandemic #Covid19Pandemic #CloudKitchens #Delivery #CloudTechnology"}]', 'https://static.wixstatic.com/media/a77ed6_00a5a3f6e8cb4406a5f4d3c760f3b917~mv2.png', 'Kitchen Operations', 'eatOS Staff', '2022-08-17', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('can-food-influencers-survive-a-pandemic', 'Can Food Influencers Survive a Pandemic?', 'Influencers were social media royalty; whether they were raising awareness for important causes or shaping the commercial landscape with sponsored posts, everyone wanted to be one of those paid accounts with loyal...', '[{"type":"p","text":"Influencers were social media royalty; whether they were raising awareness for important causes or shaping the commercial landscape with sponsored posts, everyone wanted to be one of those paid accounts with loyal followers’ legion. Every industry has influencers that fit their niche: For restaurants, it was food influencers."},{"type":"p","text":"Since COVID-19, the landscape has completely changed. Influencers are no longer saturating feeds with sponsored contentin part because many brands are going out of business and don’t have the disposable funds to hire influencers in the first place, but also because “celebrity culture” as a whole is shifting…and not in their favor. For the food service industry especially, approximately half of all restaurants have permanently closed because of the virus and the rest remain in steep trouble. Food influencers are running out of businesses to promote."},{"type":"h2","text":"What is a food influencer?"},{"type":"p","text":"Restaurants are different from most other small businesses, because they provide service as well as a product, and none of it is mass produced. Fundamentally, their relationship with influencers differs too because they’re not necessarily trying to get people to try a new product line or specific item. Instead, food influencers post about good menus, delicious meals and positive experiences with the staff."},{"type":"p","text":"Restaurants and chefs love food influencers; theyre a quick, cost-effective way to get promoted on social media. Some influencers will do it for something as cheap as a free meal, which is an extremely inexpensive price point compared to traditional advertising methods like hiring a PR team or developing a more in-depth marketing campaign involving commercials or widespread internet ads."},{"type":"p","text":"Although well-established restaurants should consider influencer marketing _in addition to_ more traditional forms of advertising, partnerships are great for getting your name out there when youre first opening and need revenue but don’t have a lot, or any, income to spare. If you can get even one influencer to eat at your restaurant and make a video, picture or positive post, you can garner a massive amount of customers in a short amount of time for a relatively low cost."},{"type":"p","text":"Consider this on a micro scale: In June, Ariana Grande posted her support for a black-owned coffee shop. Within half an hour, they had 150 new customers lined up out the door. Although in most cases, you’ll work with smaller influencers who don’t garner _quite_ as much attention (and especially in so short a time frame), this demonstrates just how powerful influence and privilege can be."},{"type":"h2","text":"Where do they stand after COVID-19?"},{"type":"p","text":"The coronavirus pandemic’s onset had an interesting impact on celebrity culture as we know it, forever changing the landscape of influencer marketing as a result."},{"type":"p","text":"Consumers have been questioning who’s speaking, what they’re saying and whether they’ve “earned” the respect and power that their massive platforms afford them. Who gets to speak? What do they really have to _say_? Is it meaningful?"},{"type":"p","text":"More and more, people are looking for authenticity and message; they want to hear something that’s useful to them, beneficial to others or uplifting marginalized communitiesespecially during COVID-19, when so many people are struggling. Anyone who wants to help needs a reliable way to determine where they should put their attention. If an influencer is promoting a skin rejuvenator, their fans are going to ask: Why are you showing me this when I lost my job and dont have the disposable income for luxury nonessentials? Why this instead of promoting businesses owned by marginalized individuals? What are you doing to help struggling people in the community? How can we raise awareness for people in a financial bind because of COVID-19? _How can we connect with others looking to build a better world?_"},{"type":"p","text":"As the conversation begins to shift toward tearing down ineffective systems and dismantling racist, sexist, transphobic, homophobic and classist power structures, consumers have also started to notice how those systemic institutions manifest in disparity on the micro-level. There’s severe racial disparity baked into influencer culture itselfeven amongst celebrity foodies. Consider the recent scandal that rocked the popular show _Bon Appétit_, when chefs of color reported lesser pay and blanket tokenization at the hands of producers and their white costars. They were used as the lone voice of their culture and underpaid, undervalued and dismissed despite that. People are beginning to notice. How can you accurately critique systems of marginalization without mentioning how you’re directly benefiting from them? Celebrity culture is changing at its core."},{"type":"p","text":"That’s not to say that influencers have lost all theirwell, their influence, as the reaction to Ariana Grande’s public support demonstrates neatly. Nonetheless, if consumers stop listening to micro-influencers and nano-influencers then restaurants don’t have any incentive to hire them. What good is a platform if nobody cares what you have to say?"},{"type":"p","text":"From the merchant perspective, there’s more undermining food influencers besides waning audience support. COVID-19 has made funds extremely tight. The pandemic hit the restaurant industry particularly hard, as being designated a nonessential business means subjection to forced closures and legislation dictating how many customers they can serve. Theyre pulling in less revenue than usual across the boardand they already operated on thin profit margins before all this went down."},{"type":"p","text":"As many as half of all restaurants have had to close, and many more face the same fate because they can’t open, either for legal or moral reasons against doing so. There hasn’t been sufficient federal aid to assist them, either. Few restaurants received PPP loans, and those that did found that the money didn’t stretch as far as they hoped. Restaurants are going under all around the U.S., and they can’t afford to comp anybody’s meal even if they had the network to reach out to food influencers right now. Even cheap labor is too expensive now."},{"type":"h2","text":"Can food influencers save themselves?"},{"type":"p","text":"Many are already trying. Some have chosen to proactively help out restaurants for free, offering advice and pro bono promotion just because they genuinely love the food there or want to support these businesses. Many influencers lost their income streams thanks to COVID-19, whether because fewer businesses wanted to hire them or because they had outside jobs that laid them off too. Now food influencers want to show the restaurants that supported them that it wasn’t just a financial relationship to them; it wasnt just a job. They actually support these businesses and want to see them recover."},{"type":"p","text":"There’s a few ways to demonstrate that sentiment, but the best method is to completely shift the focus and target of the ads that get published about these restaurants. Rather than posting a quick photo of the storefront and telling followers to try the place out, influencers are beginning to actually highlight aspects of the business that they personally love: The food, the chef, the atmosphere. Something genuine that lets their followersand restaurant managementknow that they actually, truly valued their experience and that it’s a worthwhile investment for their followers to dine there."},{"type":"p","text":"Influencers are already realizing that they need to change their strategybecause what worked before coronavirus won’t fly moving forward. People are exhausted from constant advertisements for things that they don’t want or won’t like, simply because the influencer got a hefty paycheck for the post. Similarly, restaurants need more creative ads that will actually drive consumer engagement. Interesting, out-of-the-box ideas like sharing recipes every Tuesday or promoting a favorite takeout spot for a Friday treat will encourage followers to adopt those same habits into their livesand can mean a new loyal customer moving forward."},{"type":"p","text":"Personal relationships are the only ones that will continue to thrive between restaurants and food influencers. Someone trying to exploit the struggling industry for clicks or a quick paycheck will be quickly noticed and ostracized, whereas influencers who genuinely help to uplift restaurants right now are more respected. Likewise, restaurants need to alter how they approach new partnerships. Finding the right influencer to tell your story will do more for your business than a random photo that doesn’t say much about who you are as a business; and even simply choosing influencers with a specific skill set, like video-making, will give your ad the boost it needs to stand out from the sea of other restaurants trying to catch that same attention."},{"type":"p","text":"The relationship between food influencers and restaurants need to change. Transparency and honesty between partners will be evident in those ads, conveying that same trust and genuineness to their audience. Consistency also matters when forging these new relationships, as it opens the door for true humanity as well as a sense of community. Consumers are looking to support businesses that help others who are struggling, support reform for current ineffective legislation, or contribute to their neighbors in some other, meaningful way. Cultivating that sense of community starts with your partnerships."},{"type":"p","text":"Ultimately, we need to equalize influencer culture and the restaurant industry as a whole. People have noticed the systems of inequality that plague our society, and reform has to happen on all levels or the system will never change. It starts at home: More influencers need to support restaurants owned by POC, and more restaurants need to contract with influencers of color too. Restaurants and influencers have to work together to bridge inequality, not exacerbate itthey need to, for either group to survive this pandemic intact."},{"type":"p","text":"#eatOS #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_80613a89d88249529cb36d3e1e5296de~mv2.jpeg', 'Marketing & Loyalty', 'eatOS Staff', '2022-08-16', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('creating-your-perfect-menu', 'Creating Your Perfect Menu', 'The menu: The focal point of a restaurant. If guests remember one thing, it’s the readability, style and content of your menu. However, creating an effective one takes more work than you might think. For instance, did...', '[{"type":"p","text":"The menu: The focal point of a restaurant. If guests remember one thing, it’s the readability, style and content of your menu. However, creating an effective one takes more work than you might think. For instance, did you know that where you place items has a huge effect on ordering habits? Simply changing a dish’s spot on the page can have a massive impact on your bottom line."},{"type":"p","text":"When engineering your menu, consult extensively with your head chef about what you want to offer on it; as long as they understand the vision that you have for your restaurant, together you can create a wonderful assortment of options that emphasizes their skillset and style. Involving them throughout this process ensures that every dish has their special touch to make it unique, and that will make you stand out to customers. However, your input as the owner is also crucial to ensure that the menu aligns with the atmosphere and intended clientele, that the prices match the dishes and that the menu overall adds value to your restaurant."},{"type":"p","text":"You should have already spoken to your community when you were scouting for a location and thus understand how other restaurants in the area operate and how they designed their own menus. Thus, when considering your prices, use that knowledge to compare your menu with similar dishes sold by your competitors. Competitive pricing could be the deciding factor somebody uses to choose between you and the place down the street. Of course, you also need to make a profit and make sure that what you charge matches what you offer; consider competitive pricing, but that should not be the only factor you use to evaluate your prices."},{"type":"p","text":"Subscribe with eatOS today to learn more about how to make your restaurant a success."}]', 'https://static.wixstatic.com/media/a77ed6_91adef891a4249889e6492b3eb790bad~mv2.jpg', 'Kitchen Operations', 'eatOS Staff', '2022-08-11', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('eatokra-the-app-changing-the-game-for-black-owned-businesses', 'EatOkra: The App Changing the Game for Black-Owned Businesses', 'In 2016, Anthony and Janique Edwards wanted to find black-owned restaurants in New York that they could support. They kept getting directed to the same trendy, popular locations but had difficulty discovering smaller,...', '[{"type":"p","text":"In 2016, Anthony and Janique Edwards wanted to find black-owned restaurants in New York that they could support. They kept getting directed to the same trendy, popular locations but had difficulty discovering smaller, lesser-known restaurants like the ones that they wanted to support. During their search, they found a lot of press releases and blogs about these lesser-known locations but nothing that compiled these restaurants together to give them the attention they deserved."},{"type":"p","text":"Anthony and Janique Edwards decided to solve this problem themselves. Thus, EatOkra was born."},{"type":"h2","text":"What is EatOkra?"},{"type":"p","text":"Though it started small because they’re self-funded, the app now spans more than thirty cities around the U.S. including New York City, D.C. and New Orleans. They cover eateries big and small, from restaurants to coffee houses to pop-ups and food trucks. It’s compatible for both Apple and Android and grows primarily through word-of-mouth; because the couple funds the app with their own money, they don’t have excess to spend on advertising."},{"type":"p","text":"It’s fitting, anyway, since the app communally sources their information: Users submit their favorite restaurants to the directory, either by choosing “add business” on the app or messaging the company on their social medias. People can also rate restaurants through one of four emojis and the founders have plans to add the ability to review restaurants as well."},{"type":"p","text":"The app has four categories to help users find what they’re craving: Caribbean cuisine, breakfast and brunch, soul food and local eats. They even include directions so that users can easily find their way to new locations they want to try."},{"type":"p","text":"They chose to use “okra” in the name as an homage. Okra is a seed snuck over to the U.S. during the slave trade. It’s now a culturally relevant ingredient in a lot of cuisines and as such is a fitting name for an app that brings black-owned restaurants into prominence and facilitates a greater sense of community."},{"type":"h2","text":"Why is it so important to support black-owned businesses?"},{"type":"p","text":"Supporting independent small businesses like restaurants is always important. They operate under extremely thin profit margins so it’s necessary to patronize them to help them stay in business."},{"type":"p","text":"Now the world is in flux. Times are unprecedented; the COVID-19 pandemic has raged in the country since March, when widespread shutdown orders made people take the virus more seriously. Restaurants have shut down for months and only got license to reopen their dine-in services within the past few weeks, some early as May and others late as June. After only having takeout and delivery services open for months, if they didn’t close down completely, they can still only seat a limited amount of dine-in customers. Thus many of these restaurants still aren’t turning a significant amount of profit, and small businesses continue to suffer."},{"type":"p","text":"Just as states started to reopen nonessential services all over the country, the death of George Floyd in police custody sparked Black Lives Matter demonstrations all around the world which snowballed into a much larger movement advocating against police brutality and for dismantling systemic oppression against black people in America. Many people want to show their support however they can; for a lot of them, that means patronizing black-owned businesses to show solidarity with, and give funds to, the black community during this time."},{"type":"p","text":"This isn’t an isolated incident: EatOkra has noticed a recurring trend where they see a sharp spike in users after racially-charged incidents garner national attention. The recent Black Lives Matter protests led to a 4450% increase in daily downloads of EatOkra, and they’re not the only directory for black-owned businesses that experienced newfound popularity, though they did experience the most. Black Wallet, Black Nation and more all saw a steep increase in downloads immediately following Black Lives Matter protests."},{"type":"p","text":"The support isn’t just because people want to find and support the black community right now, although that is a factor; however EatOkra also provides, as the founders describe it, a safe gathering place for people of color to “meet and eat without fear of profiling and harassment.”"},{"type":"p","text":"To foster a sense of community, EatOkra’s next goal is to connect owners and chefs with local organizations and community initiatives that combat food insecurity, helping individuals and families put food on the table."},{"type":"p","text":"When Anthony and Janique sought to uplift and support the black community, they thought that supporting them via food was the best way to bring people together."},{"type":"p","text":"In their own words, the inspiration for EatOkra came from the deep-rooted belief that this is the best way to support these businesses and help hungry customers in the process: “Nothing embodies this idea of community more than the act of feeding someone or coming together to eat or be fed.”"},{"type":"p","text":"#Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_1b2c91d977e548149d2b6287b6a02836~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2022-08-10', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('ghost-kitchens-on-the-rise-or-almost-over', 'Ghost Kitchens: On the Rise or Almost Over?', 'This past year, restaurants have contended with COVID-19 outbreaks, capacity restrictions, financial distress and so much more. Sit-down service quickly gave way to takeout and delivery; restaurants seized any trend...', '[{"type":"p","text":"This past year, restaurants have contended with COVID-19 outbreaks, capacity restrictions, financial distress and so much more. Sit-down service quickly gave way to takeout and delivery; restaurants seized any trend that would keep them open. Soon, ghost kitchens began to boom."},{"type":"p","text":"Photo courtesy of eatOS"},{"type":"h2","text":"Ghost Kitchens"},{"type":"p","text":"Though they’ve existed for years already, ghost kitchens never thrived to this extent. They’re also known as cloud kitchens:"},{"type":"p","text":"> With a traditional \\[ghost\\] kitchen, you rent a space to operate your kitchen out of and only hire the staff necessary to run it. These “virtual restaurants” only offer delivery services with no option to dine-in or pick-up at all. They don’t need front-of-house staff because customers only have the option to order online."},{"type":"p","text":"It’s clear why the pandemic has made ghost kitchens so popular. You only need to hire back-of-house staff because there’s no front-of-house for the customers to interact with. Employees are secluded and you can assign them to particular stations to ensure as much social distance as possible. Meanwhile, your restaurant still capitalizes on delivery streams which is the most important driver of revenue right now."},{"type":"p","text":"Some ghost kitchens are adapting, though. Most of the time, ghost kitchens don’t offer takeout although some have put in pickup windows for this purpose. Now you might also consider hiring a food runner to bring dishes out to customers when you integrate with curbside pickup services."},{"type":"h2","text":"Curbside Pickup"},{"type":"p","text":"Customers and service workers don’t have to meet face-to-face when they come to get their food. Some restaurants cordoned off designated parking for customers to pull up when their order is ready. A courier then brings it over and leaves it beside the car, eliminating face-to-face contact without piling on delivery fees. If you’re a restaurant currently using third-party services for your delivery channels, you know how high their commission fees can climb. Emphasizing more cost-effective revenue streams like curbside pickup just makes sense."},{"type":"p","text":"Full-service restaurants use this too. It’s safer compared to going inside and waiting in line, so why not eliminate the dining room floor altogether? Forget the wasted space when you combine curbside pickup services with ghost kitchens."},{"type":"h2","text":"Ghost Kitchens and Curbside Pickup Together"},{"type":"p","text":"We’re finally seeing signs that this pandemic is really ending, but these trends won’t die with it. This past year of stagnation has made people eager to get on with their lives as planned. New businesses open every month and more will follow as vaccinations roll out. Focus on your back of house operations and dedicate sales energy to curbside service. These two go hand in hand."},{"type":"p","text":"Studies predict that contactless and off-premise ordering will keep trending after the pandemic passes. That means that ghost kitchens will stay a safe bet, too. It’s important, now, to expend energy on profitable revenue channels that guarantee customer satisfaction. Guests are more comfortable using these safe and efficient methods; they see the benefits of self-ordering like greater accuracy and convenience. It makes sense that, after more than a year of getting very comfortable like this, they’d continue ordering online and taking their meals home to enjoy in front of their TV on a cozy couch."},{"type":"p","text":"Ghost kitchens adapted to prioritize curbside services are a more affordable venture with some measure of built-in flexibility. With this, you’ll be better prepared for any unexpected circumstances that come up in the future."}]', 'https://static.wixstatic.com/media/a77ed6_d123bc7bdaf940fa9a17b22f7454b31d~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-08-05', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('here-s-why-every-restaurant-should-use-recipe-cards', 'Here’s Why Every Restaurant Should Use Recipe Cards', 'No matter what your restaurant serves or how experienced a kitchen staff youve got, every one of them will benefit from recipe cards. They’re an especially helpful tool when training new back-of-house staff because...', '[{"type":"p","text":"No matter what your restaurant serves or how experienced a kitchen staff youve got, every one of them will benefit from recipe cards. They’re an especially helpful tool when training new back-of-house staff because recipe cards are an easy reference for them to use, which improves overall food quality and consistency, reduces food waste, stabilizes your profits and leads to happier customers."},{"type":"p","text":"Even the best chef can forget a step in the process every now and then. With recipe cards, silly mistakes will never happen again and every dish comes out perfect, every single time."},{"type":"h2","text":"What is a recipe card?"},{"type":"p","text":"It’s exactly what it sounds like: A note card or page where you write down everything about each dish that your restaurant serves. From the recipe to the ingredients to cooking procedures to plating, this is the go-to cheat-sheet for everything on the menu."},{"type":"p","text":"Since they’re meant to be referenced, recipe cards work best when they’re easily available. Print them out and give them to every staff member, put them online for cooks to check from their phones, compile them in a binder or post them on the wall so anyone can go back to them whenever they need. Spills, burns and sloppy hands are bound to happen in a kitchen, so take care to keep the cards neat and protected with lamination or similar protection."},{"type":"h2","text":"Template"},{"type":"p","text":"To make sure that all the cards are comprehensive and every dish gets the same amount of time and attention, you should use the same basic template for every recipe card. You can save pre-made templates to reuse again and again. Here’s what you need:"},{"type":"p","text":"01. Name of the recipe."},{"type":"p","text":"02. The chef who created it. Workers will know exactly who to ask if they have any questions."},{"type":"p","text":"03. Prep time."},{"type":"p","text":"04. Menu information. Include the description of the item, what meal it’s for (breakfast, lunch or dinner), what category it falls under (soups, sandwiches, etc.), and anything else thats listed on the menu so cooks understand the customer’s expectations about the food they’re making."},{"type":"p","text":"05. Serving size. The recipe yield and serving size on the card helps standardize each portion and reduces food waste."},{"type":"p","text":"06. Ingredients. This is straightforward for recipes: Include the quantity and measurement of each ingredient so that cooks can replicate it perfectly every time."},{"type":"p","text":"07. Directions. Also pretty standard, each card should tell cooks exactly how to make the dish."},{"type":"p","text":"08. Allergy information."},{"type":"p","text":"09. Storage notes and shelf life. Get better quality meals and reduce food waste when you eliminate storage mistakes."},{"type":"p","text":"10. Last revised date. Cooks will know that they’re following the latest instructions."},{"type":"p","text":"11. Plating notes. This standardizes the end presentation so every customer receives the same, aesthetically-pleasing meal when they order that particular dish. It’s a small but extremely important aspect of production that shouldn’t get overlooked."},{"type":"p","text":"12. Photo. Including a picture of what the finished product should look like makes following all these instructions even easier."},{"type":"p","text":"Depending on the knowledge and expertise of your kitchen staff, you can use “chef speak” on your recipe cards, using effective shorthand without sacrificing clarity. If you hire greener cooks, new to the industry, you should be more detailed on the cards. However, consider using a mix of industry lingo and detailed language to train your new cooks on in-the-know shorthand, which will make them more efficient and better prepare them for their careers."},{"type":"p","text":"Once youve finished writing out each one, test the cards! Good assessments work best when tried by an employee that doesn’t know the recipe very well, because you can see if the cards are clear or whether they need adjustments somewhere along the line."},{"type":"p","text":"When a recipe card is certifiably useful, you can begin using them during training sessions so that they’re an integrated part of the kitchen from the jump. Train new chefs on each dish, first by shadowing an experienced cook and then again with only the card for direction; that way, youll know when newbies are ready to handle making dishes on their own."},{"type":"h2","text":"Creating the Card"},{"type":"p","text":"You know everything that needs to go on the recipe cards, and now you need to actually create them. Websites like Canva have some free, pre-made templates that you can fill in, but you could also create them from scratch with Microsoft Office programs if you prefer a lot of customization. Whatever you choose, make sure to save the template so that you can go back and update or edit the recipe, and easily add new ones in the same style and level of detail as the rest."},{"type":"p","text":"Recipe cards make back-of-house training simple and help you provide high-quality meals for every guest. Take the time to make some effective cards and upgrade all your dishes so they come out perfect, every single time."},{"type":"p","text":"#eatOS #FoodService #RestaurantBusiness #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_b67ec25c3be54faaae4f2879bdc79f52~mv2.jpeg', 'Kitchen Operations', 'eatOS Staff', '2022-08-04', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('hospitality-is-now-entirely-touch-free', 'Hospitality is Now Entirely Touch-Free', 'Over the past several years, the restaurant industry has watched its best customers move steadily and reliably toward digitized services that are, as a result, becoming more popular everywhere from small fine dining...', '[{"type":"p","text":"Over the past several years, the restaurant industry has watched its best customers move steadily and reliably toward digitized services that are, as a result, becoming more popular everywhere from small fine dining establishments to chain QSRs."},{"type":"p","text":"Digital menus especially took off with coronavirus cases, because digitization provided a way for customers to get their favorite dishes without having to worry about the concerns that were starting to hinder dine-in services. Self-ordering capabilities allowed for increased order accuracy, giving customers time to review and submit their own tickets on their own phones and own time, and also allowing them to choose contactless delivery, takeout or curbside pickup options that enforce social distance regulations."},{"type":"p","text":"orderOS is the answer. Connected through your current Point of Sale system, orderOS makes it easy and profitable to handle staff, sales data and customers all at the same time. With scan-to-order capabilities and seamless connectivity, we’ll integrate smoothly into your operations to make business safer, more efficient and more profitable than ever before."},{"type":"h2","text":"What’s the Buzz About Digital Menus?"},{"type":"p","text":"Digital menus save your staff time when they don’t have to sanitize every menu between use, and it’s better for the environment as well as your wallet not to be stuck with all those printing costs every time you want to make a slight tweak to the menu."},{"type":"p","text":"With digital menus, you no longer have to fear innovation. Make tweaks to your descriptions, upgrade the price of your best-selling dishes and fix small mistakes as soon as you catch them. All of your devices will update with the new information at once so your sales staff is always on the same page and at the top of their game."},{"type":"p","text":"Table turns naturally speed up when you use self-ordering capabilities too. When customers just scan a QR code to order their meal, pay and tip all from their own smartphone, they can complete the transaction as soon as they’re done eating. No more waiting for the server to bring over a check. The increased speed and accuracy of ordering will be a big enough draw for customers that guest loyalty will also improve along with more efficient operations. Additionally, your own branded mobile app and optimized website will allow customers to build profiles to quickly reorder their favorites meal. All of these changes are designed to streamline the customer experience and provide the best possible experience for every patron who crosses your threshold."},{"type":"h2","text":"Technology You Can Trust"},{"type":"p","text":"Despite integration of customer profiles, orderOS doesn’t save any information for your and your customers’ peace of mind. Our secure, cloud-based servers guarantee safe, fast payment that’s encrypted so there’s a much lower risk of identity theft. Additionally, transactions happen in front of them so their credit cards never even leave their sight."},{"type":"p","text":"Self-service also draws in more profit for your business because of automatic modifications and upselling features that naturally increase the size of the average check. When guests choose a certain meal, like a cheeseburger for example, the digital menu automatically suggests that they add fries to the ticket or go up a drink size. Although it’s only a couple extra dollars for the customer, this really adds up for your business over the course of a day."},{"type":"p","text":"orderOS is convenient for the modern consumer because it integrates all the technological capabilities that they’ve come to expect from a stellar restaurant experience. Give yourself a shot against competition that are clamoring for more advanced Point of Sale systems too. Give your business orderOS."},{"type":"p","text":"This pandemic has changed the trajectory of every restaurant and, indeed, every small business in the hospitality industry forever. Cafés, bars and anyone who serves food and drink understands how health and safety concerns have steeped deep into the core of restaurant operations, unlikely to shift course anytime soon. Contactless services will continue to flourish now that customers and businesses alike have seen how they help sales and overall improve business operations to provide the most seamless and efficient experience for every single patron who dines in or takes out with you."},{"type":"p","text":"Get more for less. Book a demo with eatOS today and learn why we’re the leading restaurant technology experts. The future of food service starts here."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #OnlineOrdering #RestaurantBusiness #FoodDelivery #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_6064e0aabccf4296b913a5e6492b6fbb~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2022-08-02', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-artificial-intelligence-driven-menus-can-help-your-restaurant', 'How Artificial Intelligence-Driven Menus Can Help Your Restaurant', 'Photo Courtesy eatOS', '[{"type":"p","text":"Photo Courtesy eatOS"},{"type":"p","text":"Technology is advancing faster than ever, and it’s up to restaurants to adapt to a more tech-savvy audience. AI-powered menus drive higher sales, appeal to a broader audience, and can be a safe contactless alternative during and after the pandemic."},{"type":"h2","text":"What are AI-Driven Menus?"},{"type":"p","text":"Digital and touch screen menus have been around for years, but artificial intelligence-enabled menus take digital screens a step further. Similar to how digital assistants on your phone (like Siri, Google Assistant, and Amazon Alexa) remember your preferences and settings, artificial intelligent menus also remember customer preferences, past orders, loyalty information, and much more all for the sake of smooth, seamless customer experience."},{"type":"p","text":"With access to a customer’s vital information, AI menus can also make suggestions that the customer might like, such as upselling a popular side or suggesting their most frequent order, which drives up revenue. Studies have shown that computer’s suggestions are more frequently accepted than humans’ recommendations because they are perceived to be less intrusive, less biased, and customers often feel less pressured."},{"type":"p","text":"When AI-enabled menus are run on advanced hardware like POS systems or self-service kiosks, they can often use features similar to smartphones, such as voice commands for a genuinely contactless ordering experience."},{"type":"p","text":"Perhaps the most appropriate use of AI-powered menus is the rise of online and mobile ordering. Menu suggestions can be made to prospective customers right on their mobile devices as they order for delivery or takeout."},{"type":"h2","text":"How AI-Driven Menus Increase Sales"},{"type":"p","text":"When most people see the term artificial intelligence, they think of highly advanced technology that only the most prominent businesses can afford. The truth is the more technology advances, the cheaper it becomes."},{"type":"p","text":"Think of GPS or advanced safety features in cars. Decades ago, only top-of-the-line vehicles costing over $100,000 offered screens in cars, let alone radar safety features. Today, features like back-up cameras, radar, and auto-stop functions are found on even the cheapest Kias and Hondas."},{"type":"p","text":"Similarly, artificial intelligence can be integrated seamlessly into any restaurant no matter how small for reasonable, if not minimal, prices."},{"type":"p","text":"AI takes away all the friction that can exist that may dissuade customers from ordering. Poor user experience may make a customer choose another restaurant, but the convenience of ordering their favorite foods with minimal effort will drive up sales. AI can remember preferences and build custom menus to make ordering as easy as logging into an app and pressing one or two buttons. When a user experience takes away all impediments to the end goal of buying what they want, customers are far more likely to buy more."},{"type":"p","text":"Even upselling has become smarter compared to old scripts cashiers had to follow."},{"type":"p","text":"Artificial intelligence-enabled menus can remember preferences such as if a customer usually orders a salad with their grilled salmon or mashed potatoes with their steak and may even remember how the customer prefers their steak cooked. Drinks or ideal pairings may also be suggested based on customer preference or a database."},{"type":"p","text":"AI and cloud-enabled devices can use available data about the user and the environment to make insightful suggestions such as weather-based suggestions."},{"type":"p","text":"A cold or rainy day may make the AI suggest hot soup, a warm summer day may suggest ice cream or a range of specialty drinks or a variety of promotional offers based on region, holiday and time of day (breakfast or late night)."},{"type":"p","text":"According to a study performed by McKinsey, personalization can deliver five to eight times ROI on marketing spend, and lift sales by 10 percent or more."},{"type":"p","text":"McDonalds which has added thousands of AI-driven menus in-store as well as a significant digital upgrade believes this is a significant step in the future."},{"type":"p","text":"Were leveraging technology to improve and modernize the way we connect with customers, CEO Steve Easterbrook told investors. Were confident about the road ahead."},{"type":"h2","text":"Why AI-Driven Menus are Safer"},{"type":"p","text":"AI-enabled menus on advanced hardware can also provide a safer ordering process during health crises like the COVID-19 pandemic. The CDC has approved self-service kiosks and mobile/online ordering to be the more reliable alternative to ordering in person due to fewer human interactions."},{"type":"p","text":"Avoid using or sharing items such as menus Instead, use disposable or digital menus Use touchless payment options as much as possible, stated the CDC in their _Interim Guidance for Restaurants and Bars_."},{"type":"p","text":"Many restaurants have already deployed self-service kiosks with strict cleaning guidelines as part of their pandemic reopening plans for safer operations."},{"type":"p","text":"Some national chains like Sonic and McDonald’s have experimented with the technology and began rolling out test units last year. This year, it is expected that many large national chains will be implementing the technology, and McDonald’s will be ordering tens of thousands of units for their franchisees."},{"type":"p","text":"Another benefit of bringing AI in-house is data management. By relying on third-party delivery platforms like Uber Eats and DoorDash, restaurants enable large corporations to harvest and sell user data from their communities. By taking ownership of your customer’s data directly, restaurants can ensure the data will be used ethically."},{"type":"h2","text":"Technology Baby Steps"},{"type":"p","text":"Many experts recommend integrating technology gradually. Trying to convert a business to a heavily digital company overnight may cause efficiency issues and result in wasted time, effort, and money. By slowly adding features, restaurants can figure out what they need and don’t need for optimal operations."},{"type":"p","text":"The most important step to integrating technology into a restaurant is, to begin with, upgrades that will provide the most immediate and tangible results."},{"type":"p","text":"POS systems are a great place to start, but the immediate need is to build out their digital infrastructure for many restaurants. Online and mobile ordering has become crucial to surviving during the pandemic. Many low-cost services feature a robust and customizable integration into existing new or existing websites as well as provide apps eliminating the reliance on third-party delivery apps and their outrageous commission fees."},{"type":"p","text":"Starting with online ordering also benefits from creating a database of customer preferences, sales data, and analytics. Data is one of the most valuable resources any business can have when building an advanced technology-focused business. Every insight into your community can lead to important decisions."},{"type":"p","text":"In many ways, AI-driven menus can be the first step that takes your restaurant from surviving to thriving."},{"type":"p","text":"#FoodDelivery #OnlineOrdering #RestaurantTechnologyandCOVID19 #SmallBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_6aa4e4d1f68e47f99a3c2cefa284f866~mv2.png', 'Self-Service Kiosk', 'eatOS Staff', '2022-07-28', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-create-a-valentine-s-day-promotion', 'How to Create a Valentine’s Day Promotion', 'The most romantic day of the year is almost upon us, and restaurants are wondering how the COVID-19 pandemic will shape what’s usually a massively profitable holiday. With dine-in restrictions firmly in place and most...', '[{"type":"p","text":"The most romantic day of the year is almost upon us, and restaurants are wondering how the COVID-19 pandemic will shape what’s usually a massively profitable holiday. With dine-in restrictions firmly in place and most people still careful about social distance, restaurant owners are carving opportunities to create an intimate, romantic evening for their customers at home."},{"type":"p","text":"Online ordering will play the same big role for restaurants that it has all year. Using smart Point of Sale technology like the kind powered by eatOS, you can get automated reports that show what dishes sell best and what ticket sizes usually look like on a typical Valentine’s Day. Create a strategy to most effectively bring your unique strengths from the service floor to their homes."},{"type":"h2","text":"The Best Promotional Strategy"},{"type":"p","text":"The ideal Valentine’s Day promotion varies from restaurant to restaurant, since what works for your loyal patrons won’t work in a different city. Still, there are certain sales trends that remain pretty constant regardless of where you set up shop. For example, prix fixe menus, fancy cocktails, lobster, steak and themed desserts are always popular on Valentine’s Day, and there’s no reason you can’t offer all that on a special to-go menu created just for this Sunday."},{"type":"p","text":"Despite forgoing reservations, you’ll likely get an influx of to-go orders anyway. Valentine’s Day is guaranteed to increase overall sales and individual spending per ticket. Depending on where you’re located, the day can boost sales 30-40% overall. Clearly, it’s worth investing in a promotional campaign to draw guests to you over your competitors."},{"type":"h2","text":"Marketing Ideas"},{"type":"p","text":"Thankfully, there are some easy ways to turn staple foods into cleverly themed dishes that any guest will love. From heart-shaped pizzas to pasta with pink sauce, there are a myriad of quick and easy ways to use delicious, cheap ingredients that are guaranteed to sell. Desserts typically enjoy a 50% boost in sales as well: Give a myriad of options, and make use of staple romance foods like strawberries, chocolate and red velvet."},{"type":"p","text":"There’s no one-size-fits-all for the details, but some promotional campaigns are a safe bet:"},{"type":"p","text":"1. Proposal packages. It’s the most romantic day of the year; set the mood with some prix fixe options for two, a bottle of wine and maybe a bouquet of flowers too."},{"type":"p","text":"2. Specials deals like buy one get one free entrees, complementary dessert with an order for two, or a prix fixe menu that offers multiple courses."},{"type":"p","text":"3. Use past customer data to give your best patrons something special to show your appreciation. Advanced Point of Sales record that data so you can surprise them with their favorite dessert or bottle of wine with their order."},{"type":"p","text":"4. Do something special for those singles out there. Make a menu of wings, foods you eat with your hands and lots of garlic. It’s a good time to invent punny cocktail names too."},{"type":"p","text":"Whatever promotional campaigns you decide on, make sure to announce it all across your social media, in your email newsletters, posted in the storefront window and on your website so they know why to choose you over a competitor this weekend."},{"type":"p","text":"Remind your best customers why they usually spend their romantic evenings at your restaurant by offering exclusive Valentine’s Day-themed promotions. Use online ordering technology to handle the uptick in takeout, delivery and curbside pickup orders you’ll receive this weekend and get ready to make this weekend a special night to remember for all of your best guests."},{"type":"p","text":"#eatOS #RestaurantMarketing"}]', 'https://static.wixstatic.com/media/a77ed6_65da3c7e00e945299536dad1407c016c~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2022-07-27', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-improve-your-restaurant-via-prime-cost-percentage', 'How to Improve Your Restaurant via Prime Cost Percentage', 'Your restaurant’s prime cost is one of those necessary expenses that tell you about the health and happiness of your business’s profit margin. The better you understand your prime cost, the better you can streamline...', '[{"type":"p","text":"Your restaurant’s prime cost is one of those necessary expenses that tell you about the health and happiness of your business’s profit margin. The better you understand your prime cost, the better you can streamline your operations to increase profits. Improving your revenue doesn’t always have to mean finding ways to increase sales; sometimes, you can reduce your costs instead."},{"type":"p","text":"Prime cost is a key metric, and there’s two aspects of it to consider: Bulk prime cost, A.K.A. what you spend on goods plus labor expenses; and your prime cost as a percentage of sales. Let’s break it all down."},{"type":"h2","text":"Bulk Prime Cost"},{"type":"p","text":"In general, prime cost refers to your cost of goods soldthe ingredients and products that you buycombined with your labor expenses, meaning wages, taxes, benefits, discounts and insurance. Don’t confuse prime cost with conversation costs, which refers to manufacturing and overhead, like your utilities and kitchen equipment. Prime cost is all about what you spend on paying out your staff and buying foodstuffs to sell."},{"type":"p","text":"Now that you understand a little bit more about what prime cost _is_, you can begin to use it to your advantage. But what you really need isn’t your bulk prime cost: Its your prime cost as a percentage of sales."},{"type":"h2","text":"Prime Cost as a Percent"},{"type":"p","text":"Prime cost divided by total sales: That’s the rate that really matters. It’s one of the most important key performance indicators, or KPIs, that you can leverage to improve profit margin."},{"type":"p","text":"Most restaurants average a prime cost between 74-76%. That leaves only about 25% of profit leftover to cover expenses, including rent, debt and of course what you ultimately take home. It’s no wonder this industry operates on such famously thin margins; most business owners don’t know how to streamline this KPI."},{"type":"p","text":"Ideally, aim to lower your prime cost below 60%. If you’re really ambitious you can aim for 55%. However any lower than 50% mostly likely means that you’re cutting corners, which isn’t sustainable long-term. You want to foster an environment that your customers want to come back to, a high-value experience that encourages their return. Don’t take shortcuts that will cheapen your business, because your overall profits will suffer in the end."},{"type":"h2","text":"Lowering Prime Cost"},{"type":"p","text":"Bulk prime cost changes a lot throughout the business year since business doesn’t stay steady through the seasons. That’s why looking at the number as it relates to sales is a more reliable indicator of whether or not your success is holding steady, improving or declining."},{"type":"p","text":"Use prime cost to plan out your budget. If you know certain seasons are slow, you can schedule fewer staff members during that time. Then when sales go down, your prime cost percentage won’t change too much. This is also why it’s important not to compare _your_ bulk prime cost to that of other establishments, because the number doesnt mean much in a vacuum. Your approach to sales, the ingredients you buy, how you manage your staff and other labor costs all vary which has a significant effect on bulk prime cost, so looking at it as a percent of your sales is much more valuable and gives you the full picture."},{"type":"p","text":"Track this number regularly to stay informed. With COVID-19 still rampant, you especially need to be able to adjust operations at the drop of a hat. The restaurant industry has taken a particularly significant hit throughout the pandemic, and it’s no more stable now. Regularly examining your prime cost percentage means that youll notice downturns before its too late, and course-correct if you’re flexible enough."},{"type":"p","text":"How do you adjust your prime cost percentage? Frankly, a lot of it is about planninganother reason why keeping track is so important. If you set a goal, a target to reach each year, then your weekly or monthly progress reports act like a roadmap. A good Point of Sale system watches over all the necessary reports for you, auto-generating the work so all you have to do is analyze the output and make adjustments as you see fit. For example, you can redesign the menu to lower COGS, promote best-selling items more effectively, raise prices or decrease portion sizes. However be careful; customers may not respond well to big changes like that, and it might not be worth what it does to overall sales. Learn more about optimizing your menu through Artificial Intelligence."},{"type":"p","text":"Whatever changes you make, if your sales stay the same then your prime cost percentage will improve. Schedule a demo with eatOS and well show you how our Point of Sale system makes bolstering business operations easier than ever."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurants #Finance"}]', 'https://static.wixstatic.com/media/a77ed6_d15e53c32dba412891287bd94a15834f~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2022-07-22', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-name-your-restaurant', 'How to Name Your Restaurant', 'When opening up a new restaurant, especially for the first time, owners should pour their time and effort into finding the perfect name for it. Your name should encompass your brand and reflect your food, mission...', '[{"type":"p","text":"When opening up a new restaurant, especially for the first time, owners should pour their time and effort into finding the perfect name for it. Your name should encompass your brand and reflect your food, mission statement, concept or values."},{"type":"p","text":"You want to keep it simple, something that isn’t too hard to spell or remember. Word-of-mouth marketing is everything to a new business, so youll benefit most if people can easily look you up. Names can also evoke emotion if you want to tie a specific feeling to your brand name."},{"type":"p","text":"Whatever route you decide to go, do your research. There’s no need to commit to the first thing you think of and end up settling when theres a better name out there. Take time to find a name that’s right for you. Avoid taking one that’s already being used by checking the Secretary of State website, which is also where you’ll end up registering your restaurant’s name later on. Clarify the direction you want to explore or the message you want to send with your name; thats a great jump-off point if youre unsure where to start."},{"type":"h2","text":"What to Draw From"},{"type":"p","text":"First, decide what kind of feeling you want to convey with your name, then work backwards from there to find a name that suits that mission best. There are several different approaches that you can take to find your name."},{"type":"h2","text":"Mission Statement"},{"type":"p","text":"Perhaps the most straightforward option, naming your restaurant after an aspect of your mission statement is one of the more obvious ways to express your core values. Your mission statement already exists and encompasses who you are and what you believe in, so it’s an accessible well to draw from. If you don’t have a mission statement yet, this is a sign that it’s time to write one up."},{"type":"h2","text":"Location"},{"type":"p","text":"Naming your restaurant after something nearby is a neon sign telling new customers where to go. Referencing your street name, for example, makes it easy for customers to locate you for a visit. You can similarly name yourself after an address number, neighborhood or nearby landmark to orient new customers too. Location-based names are easy to remember, tell guests exactly where to find you and also ties you to the community in a concrete way that strengthens your relationship with the locals."},{"type":"h2","text":"Funny"},{"type":"p","text":"People enjoy a dose of good humor, but this is one of the more difficult ways to name a business. You need balance with funny names; if you take it too far then people could get offended or it could go over your customers’ heads, both of which will negatively impact your reputation. Keep it simple."},{"type":"p","text":"When it comes to funny restaurant names, it’s best to give them a test drive first. Find a group of diverse-thinking but trustworthy individuals and see if the name lands right with them before moving forward. There’s more room for creativity with a humorous or punny name, but don’t get so weighed down in being clever that it ends up making no sense with the business itself."},{"type":"h2","text":"Reference"},{"type":"p","text":"Does your location site have a history? You could pay homage to past tenants or famous local events if there are any significant ones from the area that you want to link to your brand. Alternatively, you could reference pop culture if any media has been particularly impactful on you, although be wary that your preferences could change over time and pop culture rarely has a long lifecycle, so you’ll want to choose something that has a good chance of longevity. A name that doubles as a reference can be especially advantageous if your restaurant has some kind of relevant theme."},{"type":"h2","text":"Emotional"},{"type":"p","text":"Your name can even trigger an emotional response in customers which ties your brand positively to their feelings and encourages return trips. Warmly welcome guests to make them feel at home when they choose to dine with you, so that they’ll want to come back next time they’re wondering about where to eat out. You can make customers feel happy, nostalgic or simply at home, strengthening your relationship with each other."},{"type":"h2","text":"What’s in a Name?"},{"type":"p","text":"Your restaurant’s name is an important brand choice, and you have a chance here to get creative and reflect on your values and uniqueness. The name is how people will forever identify you, so choose wisely."},{"type":"p","text":"Workshop ideas with those same friends you used to rule out humorous names and gather opinions on the choice you like best before locking it in. Don’t settle for something so important as a brand name; plan ahead. You should put as much time and effort into this as you do your decor, menu and every other aspect of your restaurant which reflects so much of your heart and hard work."},{"type":"p","text":"Finding a name that matches your price point, brand voice and overall atmosphere can be a challenge. Reviewing these categories might spark the perfect fit, but they’re only a jumping off point for most restaurateurs. Use this guide to begin generating ideas, but remember: The perfect name will feel right and click into place. Make sure you give yourself the time and space to find the right fit."},{"type":"p","text":"#Branding #RestaurantMarketing #eatOS #RestaurantBusiness #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_3872a81875ac45debb8b5372ac6435d6~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2022-07-21', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('25-restaurant-terms-to-know', '25 Restaurant Terms to Know', 'If you spend a lot of time in and around the food service business, you’ll notice a lot of industry-specific lingo that may seem incomprehensible to outsiders. For employees new to the industry, owners hoping to grow a...', '[{"type":"p","text":"If you spend a lot of time in and around the food service business, you’ll notice a lot of industry-specific lingo that may seem incomprehensible to outsiders. For employees new to the industry, owners hoping to grow a new venture or companies that service restaurants as clients, it’s important to know the terminology that will pervade the front and back of the house."},{"type":"p","text":"Here are 25 restaurant industry terms you should know to keep your restaurant, or restaurant-adjacent business, running smoothly."},{"type":"p","text":"01. All day: The total amount of each item thats needed from the kitchen, often used when there are multiple ticket orders in queue. For example, if one customer ordered a BLT and fries, another ordered a milkshake and fries, and another ordered a BLT and a salad, you might say, “two BLTs, two fries, one milkshake and one salad all day.”"},{"type":"p","text":"02. Back of house: Everything behind the scenes that the dining room and bar (which are also known as the “front of house”) dont see. In a typical establishment, this encompasses kitchen, offices, storage areas and prep stations."},{"type":"p","text":"03. Combo meal: A combination meal, or combo meal, is an all-in-one order that typically includes an entree, side dish and a beverage. Though most often found at QSRs, combo meals appear at fast casual and fine dining restaurants as well."},{"type":"p","text":"04. Drop the check: Fairly straightforward, this means to bring a table its bill."},{"type":"p","text":"05. Early bird special: A dinner special that happens earlier than regular dinner menus are served; typically for elderly customers or anyone who wants a large meal for a steep discount, generally tourists."},{"type":"p","text":"06. Fire: The head chef will say this when they’re ready to begin making or prepping a certain meal."},{"type":"p","text":"07. Ghost kitchen: A completely virtual restaurant where the owner only rents out kitchen space. It sells food exclusively, or almost exclusively, through delivery services (a few offer takeout options as well). Learn more about ghost kitchens and why they’re becoming more popular."},{"type":"p","text":"08. Happy hour: A time frame when restaurants typically offer drink specials and discounts on bar food, or sometimes even free meals. It’s a popular tactic to drive more customers in during your off-peak hours."},{"type":"p","text":"09. In the weeds: This indicates that it’s a stressful, busy time for the restaurant. Typically theres a lot to do and very little time to accomplish it all."},{"type":"p","text":"10. Jumpin’: A restaurant that’s very busy, lively and/or profitable."},{"type":"p","text":"11. Kill it: When a customer requests something overcooked, you might tell the kitchen staff to “kill it."},{"type":"p","text":"12. Last call: A warning that a kitchen or bar is about to close, so customers who want to add on to their order should do so now."},{"type":"p","text":"13. Mise en place: A French phrase that means “putting in place” and ensures the kitchen staff follows proper procedure, such as prepping ingredients and readying all their cookware, before service starts and meal prep begins."},{"type":"p","text":"14. No-show: A customer who doesn’t arrive on time for their reservation, at which point staff can seat other guests in their stead."},{"type":"p","text":"15. On the fly: Something that needs to be done quickly and with little warning. Servers will say something to the cooks like, “Table 4 was dissatisfied with their chicken parmesan. I need a new special on the fly!”"},{"type":"p","text":"16. Push it: Usually in reference to a particular ingredient, item or deal that management wants servers to upsell."},{"type":"p","text":"17. Quote: The estimated wait time it will take before a customer will be seated on a busy night."},{"type":"p","text":"18. Runner: The staff member whose job it is to bring dishes and empty plates back and forth between the kitchen and dining room."},{"type":"p","text":"19. Signature dish: A specialty meal that’s unique to either the restaurant itself or one of their chefs."},{"type":"p","text":"20. Table turn: How many customers go through the entire meal, from being seated to payment, within a certain time frame or throughout the day."},{"type":"p","text":"21. Upselling: When servers push customers to add on ingredients, increase their portion sizes or take advantage of special deals with the goal of raising the overall ticket size."},{"type":"p","text":"22. Value meal: A combination of menu items that are sold together for less than the sum of their individual parts. Though most common at QSRs, any restaurant can have their own value meal."},{"type":"p","text":"23. Walk-in: This either references a walk-in freezer for storage, or a customer who comes in for service without a reservation first."},{"type":"p","text":"24. 5 out: Indicates to the rest of the kitchen that a dish will be ready to plate in five minutes."},{"type":"p","text":"25. 86: To nix an order because the kitchen cannot prepare it for whatever reason, such as running out of a key ingredient."},{"type":"p","text":"These are just a few of the phrases you’ll need to know once you get your new career in the restaurant industry off the ground."},{"type":"p","text":"Have you heard of any other common restaurant terms? Let us know in the comments!"},{"type":"p","text":"#eatOS #FoodService"}]', 'https://static.wixstatic.com/media/a77ed6_204425db9ddd42eb9bc591e258d13b81~mv2.jpeg', 'Kitchen Operations', 'eatOS Staff', '2022-07-19', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('4-creative-delivery-strategies-to-help-the-community', '4 Creative Delivery Strategies to Help the Community', 'Everyone has felt the effects of business closures, loss of income and a moratorium on public gatherings because of COVID-19 and the subsequent mass isolation measures put in place around the globe.', '[{"type":"p","text":"Everyone has felt the effects of business closures, loss of income and a moratorium on public gatherings because of COVID-19 and the subsequent mass isolation measures put in place around the globe."},{"type":"p","text":"Still, while restaurants all over wonder if they’ll have to shut their doors, some have found creative ways to connect with their community and help out individuals currently struggling as much as their business. Some incredible restaurants have modified their ordering and delivery strategy in novel ways to support the customers and communities that have always supported them."},{"type":"h2","text":"1\\. Pay-what-you-can"},{"type":"p","text":"Many restaurant owners understand that if they’re having trouble staying afloat, their customers likely find themselves in a similarly complicated financial situation. Because of this, many restaurants across the U.S. have implemented a “pay-what-you-can” strategy in the hopes of helping their local communities during this trying time."},{"type":"p","text":"Although some might take advantage of this, restaurants hope that people recognize the value of hard work and understand that the staff risks infection every day so that customers can have food on their tables. Thus much like tipping delivery drivers, people will likely pay what’s owed these daysif they can afford itor possibly even more if they have money to spare. With this model, everyone can support local community members who do need to pay a little bit less than usual because of the recent economic downturn."},{"type":"h2","text":"2\\. Rotating menus"},{"type":"p","text":"Other local restaurants have discovered the untapped potential of rotating menus. Whereas the majority of restaurants have a set, expansive selection of dishes to choose from, other establishments, typically higher-end fine dining, have always routinely switched out their selections. Now, other businesses have begun taking advantage of this same trend."},{"type":"p","text":"Twisted Soul in Atlanta, Georgia has started doing exactly that. Depending on their inventory each week, they offer different menus that rotate out, and they no longer open every day either. This method has several different benefits: For one, they only require a few cooks at a time rather than the usual, entire robust kitchen. This saves money on labor costs and prevents overstaffing during the inevitable downtime. Reducing their business hours furthers this end as well."},{"type":"h2","text":"3\\. Groceries"},{"type":"p","text":"Markets carries a lot of fear and stigma nowadays. People breaking the six foot distancing rule out of necessity, cashiers who have processed a lot of people’s groceries that day, items that have been touched by countless hands on the shelves. Although you can avoid these concerns to an extentgoing during off-peak hours, for example, using the self-checkout machine and remembering that items like boxes and food have no known ability to carry the virussome restaurants now offer another alternative: Delivering groceries."},{"type":"p","text":"Though platforms like Instacart were built to provide this service, some restaurants now let you order certain groceries, like overflow ingredients, along with your actual meal. Many people find this a great way to get the necessities while staying sheltered in place. One restaurant called Tesse in West Hollywood has taken this concept even further: They’ve now temporarily become Tesse’s Market, and they offer produce, bread, eggs and more products that have long since become difficult to find on stores’ shelves. Other restaurants take a different route and offer needed goods, like toilet paper, for free with all regular purchases."},{"type":"h2","text":"4\\. Alcohol"},{"type":"p","text":"Some restaurants started boosting sales a different way. Previously, you couldn’t carry alcoholic beverages off the premises and you definitely couldn’t get drinks delivered. If you wanted liquor to your door, you had to use an alcohol delivery service like Minibar or a third party platform like Instacart, both of which verify your I.D. on arrival."},{"type":"p","text":"Those businesses have seen increased sales since shelter in place measures began. Food service establishments have gotten in on the trend as well. In places like California, Texas, Colorado and D.C., customers can add drinks that they would usually get during dine-in service to their order and have it delivered along with their food. Many businesses are seeing small profits from this which helps with their overall bottom line. Every sale counts."},{"type":"p","text":"As quarantines extend and more businesses have to shutter their doors, some incredible restaurants are striving to take care of their community just as they ask the community to take care of them. Many people worry about the future and the long-term effects of COVID-19. In times like these, we can still come together and find power, and kindness, in each other."}]', 'https://static.wixstatic.com/media/a77ed6_54352dcabef243ea956bdc118d0da62a~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-07-14', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('4-creative-solutions-for-food-trucks', '4 Creative Solutions for Food Trucks', 'Businesses all over the world are closing because of COVID-19 and the subsequent measures taken to reduce its spread, and people are watching their favorite restaurants suddenly board up windows and take down their open...', '[{"type":"p","text":"Businesses all over the world are closing because of COVID-19 and the subsequent measures taken to reduce its spread, and people are watching their favorite restaurants suddenly board up windows and take down their open hours. Amidst all this, has anyone noticed food trucks quietly disappearing off the streets?"},{"type":"p","text":"Because of the transitory nature of food trucks, people might not register them leaving their usual corner of the parking lot, or in fact, even be aware that they’re facing financial struggles as hard as any other business."},{"type":"p","text":"Some food trucks have actually experienced an upswing in business since COVID-19 began. This is in part because restaurants closed en masse, significantly limiting their competition and making trucks a more viable option for consumers as a result. Trucks additionally provide some added layer of security against the virus compared to traditional restaurants, as diners can easily take their food to-go or at least sit nearby in an open-air, less-populated environment. With so much variety amongst food trucks, it’s not surprising that some experienced even more business during this pandemic."},{"type":"p","text":"However, it’s not the case for most of them. To examine a microcosmic sample study that reflects the bigger picture: In Los Angeles, food trucks are struggling as social distance, widespread financial troubles and more all caused them to lose about 60-70% of business across the city’s 800 or so trucks, and they’re not alone there."},{"type":"h2","text":"Are food trucks doomed?"},{"type":"p","text":"In response to their current troubles and all the uncertainty that’s indefinitely in store for American small businesses, some food trucks have taken creative approaches to gain back customers, help their communities and generally weather the year’s ongoing storm. Like many business owners, they’re not going down without a fight."},{"type":"h2","text":"1\\. Mobile groceries"},{"type":"p","text":"One strategy to reinvigorate a business is to fill a niche that nobody else is servicing. As grocery stores become hotbeds of contentious health and sanitation debates, and people become less inclined to venture too far from home, food trucks are adapting to help ease these worries."},{"type":"p","text":"That’s why Coolhaus, an ice cream truck based in L.A., began a new, temporary venture called Bodega on Wheels. The truck still sells ice cream, but they also have produce, items for your pantry, alcohol and more. By collaborating with other L.A. businesses, they’re stocked with everything you need and drive it right up to your door. Delivery is free; just order in advance. 10% of proceeds go straight to charity too."},{"type":"p","text":"While Coolhaus and business models like it bring much-needed supplies directly to customers, some food trucks have taken to the other end of the spectrum: Some essential businesses have stayed open throughout the pandemic, and many trucks made deals to park in their lots so as to draw in customers at one of the few places that stay steadily populous. When foot traffic slows down at your usual location, you have to adaptand that’s exactly what food trucks around the country have done this spring."},{"type":"h2","text":"2\\. Aid relief"},{"type":"p","text":"While some trucks are trying to get their customers back, others shifted their attention early in the pandemic toward finding a way to pivot their business and assist their communities. They’re not the only ones struggling, and some food trucks realized there was opportunity in bridging that gap."},{"type":"p","text":"In New York, the Association of Food Trucks partnered with sponsors and began delivering supplies and meals to workers on the front lines. Thanks to their sponsors as well as food and beverage companies pitching in for the initiative, those trucks are out every day of the week with a rotating schedule that allows them to reach five to ten different hospitals every week."},{"type":"p","text":"New York food trucks aren’t alone in this either; all over the country, trucks have joined with initiatives to drop off food at hospitals, police and fire departments, feeding all kinds of frontline workers around the U.S. Some receive sponsorship, like the Association of Food Trucks, while others began working with nonprofits or started accepting meals from anonymous donors for distribution."},{"type":"h2","text":"3\\. Online ordering"},{"type":"p","text":"A major departure from a big facet of their traditional business model, some food trucks are now allowing customers to order ahead with them."},{"type":"p","text":"This is made easier for some when they partner with delivery apps designed to help with the transition; TruckBux, for example, makes it easy for food trucks to accept and decline orders, set their notifications, control the menu, track sales metrics and more. Trucks that partner with big name apps like Postmates or DoorDash get similar benefits; apps like these are a quick and easy way to expand your customer base, increase brand recognition and simplify the shift toward online ordering. Some food trucks prefer to leave the apps alone because of the associated financial burden and because they have to give up some measure of control over their final product, but others prioritize how smoothly third party apps help them move to online ordering and delivery."},{"type":"p","text":"Online ordering lets food trucks expand past their traditional delivery zones and reach a wider audience of hungry customers just waiting for them to arrive."},{"type":"h2","text":"4\\. Rest stops"},{"type":"p","text":"Recently, food trucks have been able to take advantage of a new market previously blocked off for them. In April, the Federal Highway Administration passed a ruling saying states could allow trucks to service rest stops, if they choose. California and Ohio have already taken advantage of this, allowing food trucks in those states to apply for a permit which lets them park along highways and at rest stops."},{"type":"p","text":"This is doubly beneficial; food trucks can travel further when business at their home base dries up, which plenty of cities are already seeing happen as more and more people self-isolate because of COVID-19. The new ruling comes as a big relief for truckers too: Since many roadside restaurants had to close like any other, it’s been increasingly difficult to find reliable food service in the middle of their routes. Now they have more options and are much less likely to be stuck hungry on the road for long stretches of time."},{"type":"p","text":"Hopefully, other states will also begin taking advantage of this ruling from the Federal Highway Administration, to protect their food truckers and truck drivers alike."},{"type":"h2","text":"Are their problems over?"},{"type":"p","text":"Food trucks all over the country are finding innovative solutions to troubles they never thought they’d face, but despite the great strides they’re making for their businesses and their communities, they’re not out of the woods by far."},{"type":"p","text":"Some cities are still burdened by restrictive laws that hurt operations, like in states where it’s still illegal to park along the highway or at rest stops. States are also cracking down on these trucks as part of a bid to reduce the spread of COVID-19; in Pennsylvania, for example, they mandated that food trucks can’t sell drinks to a customer who’s already finished their meal, a rule meant to prevent loitering and excessive crowds which correlate to more cases. Though it’s sensible, it also hurts food trucks because it sets parameters around customer transactions. Meanwhile in California, Los Angeles is getting serious about missing permits and shutting down more trucks because of violations."},{"type":"p","text":"Truck owners are also having difficulty getting PPP loans and other government funding. As small local businesses, they often don’t qualify for assistance and also don’t have the resources to secure Economic Injury Disaster Loans from the SBA, which tend to go to bigger businesses instead."},{"type":"p","text":"Rather than continue hemorrhaging money the way they are under the current market, a lot of food trucks simply shut down. This is problematic for a lot of their employees because a significant amount of food truck workers are undocumented immigrants, which means they can’t secure unemployment benefits while they searchfruitlessly, along with so many other unemployed Americansfor a new job."},{"type":"p","text":"Unfortunately, as long as the pandemic continues, food trucks’ regular revenue streams will most likely continue to dry up. Aside from the business they usually garner from foot traffic, these trucks also make a lot of their money by setting up shop around big events like concerts, festivals, sports games and the like, which have now been indefinitely postponed. They also can’t attend food truck meet-ups and other major functions which would normally bring a lot of their business for the year."},{"type":"p","text":"Because of these unfortunate events, food trucks need to continue experimenting with innovative business ideas that will allow them to stay afloat through these uncertain times and even thrive in new areas they never thought they’d break into, like community outreach efforts. As the past few months alone have shown, there’s always a way forward."},{"type":"p","text":"Food trucks are struggling and surviving in more ways than just the ones outlined above. Find out more about their resilience and challenges for a better understanding about how to help. Together, we can support small, hardworking businesses through this crisis and beyond."}]', 'https://static.wixstatic.com/media/a77ed6_563dce71c4ea4549a4c5b8f05e7cbc7d~mv2.jpg', 'Restaurant Insights', 'eatOS Staff', '2022-07-13', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('5-ways-eatos-makes-restaurant-management-simple', '5 Ways eatOS Makes Restaurant Management Simple', 'When you’re managing a restaurant, theres plenty to juggle: From the menu to your employees down to each individual transaction, it can be difficult to keep all of this in mind while simultaneously optimizing every...', '[{"type":"p","text":"When you’re managing a restaurant, theres plenty to juggle: From the menu to your employees down to each individual transaction, it can be difficult to keep all of this in mind while simultaneously optimizing every aspect of operations to the fullest possible extent."},{"type":"p","text":"That’s why at eatOS, we developed cutting-edge Point of Sale technology designed to make running a business easier. Our system is fast, intuitive to use, takes up less physical space than onsite storage systems and runs remotely so you can stay on top of your restaurant even when you’re not on the premises. Take advantage of the future of food service with eatOS management tools."},{"type":"p","text":"When you sign up with us, youll experience the benefits of these five features, and more, almost immediately:"},{"type":"h2","text":"1\\. Tableside Ordering"},{"type":"p","text":"Track table turn times and submit orders immediately with tableside ordering capabilities. Mobile devices, like tablets, can host eatOS software so customers order directly from their seats. This not only improves accuracy and gets meals out to their tables more quickly, but servers can focus on cultivating a superior customer experience instead. Visual menus make it easy to answer any questions that guests have and automatic upselling capabilities mean you never miss a chance to offer modifiers, sides or increased portions. Most of the most of every check."},{"type":"h2","text":"2\\. Menu Management"},{"type":"p","text":"Ordering isn’t the only part of business that experiences improvements with eatOS hard- and software. You can also optimize the menu to maximize revenue overall, or increase the profitability of certain dishes and promotions. Add photographs to the menu to encourage sales, schedule when promotions go live, and automatically send orders to the Kitchen Display System or applicable printers."},{"type":"p","text":"Inventory management goes hand in hand with an optimized menu. See the exact costs of ingredients to determine the most profitable and cost-deficient items and adjust your menu accordingly. The better you track your inventory, the better you can stay on top of reordering before you run out of ingredients and avoid costly overstocking too."},{"type":"h2","text":"3\\. Safe and Secure Payment Processing"},{"type":"p","text":"eatOS offers a variety of different payment options so your customers can always use their preferred method. The modern consumer is increasingly digital: Accept mobile, card and cash payments with EMV-enabled devices or provide pay-at-table options via tableside ordering tablets. All of this reduces errors and simplifies, as well as speeds, the transaction process overall, thus lowering the risk of theft and increasing your table turn times so you can seat more customers each day."},{"type":"h2","text":"4\\. Workforce Management"},{"type":"p","text":"An efficient restaurant can only run to the best of its ability when you have a hardworking staff to go with it. Manage your staff better than ever before when you track their activity, including when they clock in and out, their breaks, vacation times and days off so you can reduce overtime costs. Let employees clock in and out remotely from the app while geofencing capabilities simultaneously reduce timecard fraud by only allowing them to do so were theyre on the premises."},{"type":"p","text":"Payroll and scheduling is also simpler with eatOS. We’ve integrated with 7Shifts, an advanced scheduling software which makes it fast and easy to set staff schedules. Employees can also swap shifts online without managerial permission so you can focus on more important tasks. Set role permissions through eatOS to reduce theft, such as by only allowing managers to void meals; no more sneakily comping food for friends or to enjoy in the back room on break. See your performance statistics to narrow down your best and worst workers and develop a more productive staff with eatOS."},{"type":"h2","text":"5\\. Customer Relationship Management"},{"type":"p","text":"Simplify and improve every customer’s experience with the CRM features that come with our Point of Sale. Launch loyalty programs to keep better track of and incentivize return visits. Building individual customer profiles helps you form targeted marketing campaigns that increase overall revenue. Guests can also pay off outstanding bills through their account if they’ve chosen to securely link their card to their profile. All of this makes their next visit more fulfilling while giving you crucial information to form promotions and marketing campaigns that you know will resonate with your particular demographic."},{"type":"p","text":"Managing a restaurant is no small task. Simplify your workload and improve your overall efficiency with advanced eatOS technology and all of the smart capabilities that come with it. Automatically run and analyze sales and labor reports so you can pinpoint detriments to profit, know which service areas have the best table turns, and more. All of this helps you create a better customer experience, and make smarter budgeting and business decisions too."},{"type":"p","text":"At eatOS, we believe in helping restaurants like yours thrive. Build a better business with technology right from the future of food service and let eatOS simplify your managerial duties today."},{"type":"p","text":"#eatOS #RestaurantManagement"}]', 'https://static.wixstatic.com/media/a77ed6_407c3246441d453682ef33077214eeda~mv2.png', 'Point of Sale', 'eatOS Staff', '2022-07-08', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('50-of-restaurants-still-don-t-have-a-digital-solution', '50% of Restaurants Still Dont Have a Digital Solution', 'Photo Courtesy eatOS', '[{"type":"p","text":"Photo Courtesy eatOS"},{"type":"p","text":"Digital solutions have become essential during the COVID-19 pandemic for restaurants. On-premises dining has become a dangerous activity and forced customers to dine at home. When even venturing outside carries the risk of infection the natural solution is online ordering and delivery. Unfortunately, the vast majority of restaurants were not equipped with the infrastructure to support large scale online and mobile ordering."},{"type":"p","text":"Enter third-party delivery apps. Platforms like Grubhub, Uber Eats and DoorDash provide all the digital infrastructure and a delivery workforce so restaurants dont have to worry about anything other than what they were already doing. Unfortunately, the convenience and expertise they offer dont come cheap"},{"type":"p","text":"Depending on the platform, restaurants can be faced with complicated commissions and payment structures that generally range from 15%-30% per order."},{"type":"p","text":"Here are how the most common platforms break down their charges:"},{"type":"p","text":"Uber Eats: A representative stated commissions vary based on the package a restaurant chooses. For restaurants that use the app only for ordering and already have their own delivery means, the commission rates are about 15% on average. Using the app as well as their delivery service increases commissions to 15% to 30%."},{"type":"p","text":"Postmates: Postmates was acquired by UberEats in July 2020 effectively making them the second biggest delivery platform in the US. Both services continue to operate separately."},{"type":"p","text":". A company spokesperson stated the commission rates are decided on a case by case basis with each restaurant and that arbitrarily setting on-demand delivery prices has real consequences that undermine our ability to operate and kills the whole industrys ability to provide the services restaurants need to stay open. No hard numbers were given but according to various surveys from restaurants, commissions generally fall between 20%-30%."},{"type":"p","text":"DoorDash (Owns Caviar): Similarly, DoorDash representatives refused to give reliable estimates for how much commission fees cost restaurants. Surveys indicate that commission fees are most commonly between 20%-40% at the highest levels. Some restaurants have had luck reducing commission fees to 15% during the pandemic but many more restaurants have received pushback."},{"type":"p","text":"Grubhub: A Grubhub representative said their platform is free, but restaurants will have to pay 10% commission to access their delivery driver network. Restaurants will have to pay an additional 15% if they want their business featured on their app when customers use the search on their platform for delivery and pick-up options. Restaurants have pushed back saying if they dont pay for Grubhub marketing meaning featured in search options, it is doubtful that customers will be able to find their business on the platform."},{"type":"p","text":"Based on this estimate, commissions should be around 25% per order but anecdotal evidence suggests the average commission fee is approximately 30% per order."},{"type":"p","text":"Chef Ashish Alfred, the owner of three restaurants in Maryland, was clear for his disdain for the delivery platforms but acknowledge for many restaurants that do not have the resources to build out their own digital platforms, there are few other options."},{"type":"p","text":"What are we supposed to do?, he said. We can hate them all we want, but Id rather have 70 percent of something than 100 percent of nothing."},{"type":"p","text":"That nothing is a reality for many restaurants."},{"type":"p","text":"Our market data suggests that 50 percent of all restaurant operators do not have access to a digital solution today, and even those who do often cant afford it or outsource it, Tech company Toast spokesperson Tejas Kataria said."},{"type":"p","text":"Many restaurants still struggle with understanding and effectively implementing digital solutions. Other restaurants cannot afford to hand over 30% of their revenue resulting in a loss of money each time someone orders from them."},{"type":"p","text":"May Matsuo-Rose, the owner of Don Don Curry, pays 25%-33% in commissions per order to the four biggest delivery platforms."},{"type":"p","text":"Its been really difficult because they take so much commission. Its not a sustainable way to do business. Youre losing money feeding people, Matsuo-Rose says."},{"type":"p","text":"There is a steep learning curve even on convenient delivery apps."},{"type":"p","text":"Our rep at the kitchen even encouraged us to order from ourselves on these apps so we could trick the algorithm to make it seem like our restaurant is busier and more popular than it is, Matsuo-Rose says."},{"type":"p","text":"Digital algorithms dominate how viable businesses can appear on searches on each app. Less tech-savvy companies may be left in the cold even if they decide the high commission fees are worth it."},{"type":"h2","text":"Easiest Digital Solution"},{"type":"p","text":"It may sound like a dream but the easiest and best alternative to delivery apps are online services that connect your business directly to your customers, no multi-million dollar middle-man. These services can provide the digital infrastructure that restaurants need to provide online and mobile ordering but without the steep commission structure."},{"type":"p","text":"Using these tools, restaurants can customize their online ordering system integrated into Google searches and even comes with personalized mobile apps. Some estimates indicate restaurants can save at least $600 per month on commission fees alone not including having full control over marketing and brand exposure."},{"type":"p","text":"Small tech companies like eatOS offer robust features that match or exceed larger companies while also providing the individual attention that restaurants need and only small determined and agile companies can provide during these hard times."},{"type":"p","text":"Get easy to use advanced technology with world-class customer service at an affordable price. In many cases, the savings alone will pay for the service allowing restaurants to keep their profits and either save to weather out the pandemic or grow to ensure the business can hit the ground running when the pandemic ends."},{"type":"p","text":"#RestaurantTechnologyandCOVID19"}]', 'https://static.wixstatic.com/media/a77ed6_9fb6db6e1128418db7aa823f8575c152~mv2.png', 'Online Ordering', 'eatOS Staff', '2022-07-07', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('community-highlight-commonspirit-health-turns-cafes-to-grocery-stores', 'CommonSpirit Health Turns Cafes to Grocery Stores', 'Since CommonSpirit Health opened in February 2019. they’ve grown into the largest Catholic health system and second-largest nonprofit hospital chain in the United States. With more than 150K employees and 25K physicians...', '[{"type":"p","text":"Since CommonSpirit Health opened in February 2019. they’ve grown into the largest Catholic health system and second-largest nonprofit hospital chain in the United States. With more than 150K employees and 25K physicians working for them, CommonSpirit Health extends to 137 hospitals, over 1000 care sites and 21 states."},{"type":"p","text":"On 9 April 2020, they announced how they plan to support hospital employees and show their appreciation for the difficult, necessary jobs done by healthcare workers nationwide during the COVID-19 pandemic."},{"type":"h2","text":"Opening Groceries in Affiliated Hospitals"},{"type":"p","text":"To show their appreciation and assist their workers on the front lines, CommonSpirit Health has turned hospital cafes into groceries in associated institutions in Arizona and the Pacific Northwest."},{"type":"p","text":"These temporary, makeshift grocery stores are open to physicians and other staff working at those hospitals. Zoe Coleman, the clinical nurse manager at St. Joseph’s Hospital Medical Center in Arizona, said in a statement, “Our staff are working more than 12 hours every day and the grocery store allows them to feel their work is valued in a way that goes above and beyond what I can say on the floor as their manager. At the end of the day, our staff can comfortably shop for essential items and have more time to spend with their loved ones.”"},{"type":"p","text":"These markets stock necessities that have long since gone out of stock on most stores’ shelves. Available items include toilet paper, milk, eggs and disinfectant wipes so that employees can stay healthy and fed without having to face additional risk at traditional grocery stores, especially since they already have twelve hour shifts every single day taking care of their communities and thus routinely jeopardizing their health."},{"type":"p","text":"These groceries not only save them from added exposure, but also allow workers to go shopping directly after their shift without commuting to a second location. The stores remain open during the same hours that the cafes operated. This lets them spend more of their time off with their family, doing things they love and taking care of themselves just as they take care of everyone else."},{"type":"h2","text":"How is all of this possible?"},{"type":"p","text":"Throughout their tenure as a successful nonprofit organization, CommonSpirit Health has formed relationships with supply chains that allow them to acquire these coveted items, when most carriers can’t find them anywhere."},{"type":"p","text":"The personal connection to these supply chains also makes it possible for affiliated hospitals to put in customized orders for any items required by individual employees or specific to their local community."},{"type":"h2","text":"Planning for the Future"},{"type":"p","text":"Although as of now, CommonSpirit Health has only managed to establish these temporary groceries in a few of their associated hospitals, they hope to soon expand this operation to all of their affiliated establishments across the United States."},{"type":"p","text":"In addition to providing access to hard-to-find household necessities, some CEOs and executives have donated portions of their salaries to funds dedicated to helping hospital workers. Still, others have had little choice but to furlough a percentage of their workforce until hospitals have more incoming revenue to pay them all what they deserve."},{"type":"p","text":"However, not every one has had to cut costs. On top of extending their cafe-turned-groceries initiative to more hospitals in need, CommonSpirit Health is also working hard to introduce child care and other benefits so as to take away some additional burden that has befallen these workers as their hours increase."},{"type":"p","text":"As we all show our appreciation for the important but risky work performed by healthcare providers during this time, nonprofits like CommonSpirit Health are going above and beyond to demonstrate how much they value their workers while they continue to save and protect those most vulnerable in society. Members of affected communities can donate to CommonSpirit Health so that they can bring their good will and effort to more of their affiliated hospitals across the country."},{"type":"p","text":"#CommunityOutreachStrategies #CoronavirusPandemic #Covid19Pandemic #HealthandWellness"}]', 'https://static.wixstatic.com/media/a77ed6_5d4a1d91a49b4eb89d7957f9a0db550b~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2022-07-05', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('community-highlight-send-chinatown-love', 'Community Highlight: Send Chinatown Love', 'In late February, the United States hadn’t yet felt the full effects of COVID-19 that would later become a massive, months-long pandemic. Nevertheless Square, a popular Point of Sale provider for small- and medium-sized...', '[{"type":"p","text":"In late February, the United States hadn’t yet felt the full effects of COVID-19 that would later become a massive, months-long pandemic. Nevertheless Square, a popular Point of Sale provider for small- and medium-sized businesses, saw the signs and held a meeting then to determine how they would help their customers moving forward. Thus they shifted focus to begin setting up donation systems and gift cards for their merchants to ensure they still had certain revenue streams moving forward."},{"type":"p","text":"Justin Mckibben, a software engineer with Square, recognized how this primarily affected businesses who had the technological capability to accept donations and gift cards via the web and a compatible Point of Sale system. In response he connected with engineers, designers and other people he knew in the industry to found the organization Send Chinatown Love."},{"type":"p","text":"Now they have a team of thirty all working hard on their own time to support their local, New York-based community. In areas like Chinatown, many businesses are cash-only and don’t have the capability to support systems like Square. This also means that they can’t receive the financial assistance that these alternative revenue streams provide. Send Chinatown Love invented a different approach so that they can better help that community. On their webpage, they advertise how out of 6,000 businesses in Chinatown, 700 are restaurants and only 94 remain open during COVID-19. They seek to help more of them stay afloat through this crisis."},{"type":"p","text":"Because many of these businesses don’t have phone or internet, this initiative connects them to these necessary channels so that they can expand their audience and generate revenue without having to invest money they don’t have into new technology. The goal, they say, is “building an online presence for small businesses in Chinatown” so they can have access to the same resources that businesses like Square provide to restaurants that have the capability to host their services. Unfortunately, many small businesses don’t."},{"type":"p","text":"Send Chinatown Love goes directly to off-the-grid restaurants and finds out exactly what they need to thrive, then builds the resources for them. They design custom webpages for their customers that cater to each one’s individual needs and ultimately sets these restaurants up with the ability to take donations and sell gift cards or vouchers. So that restaurants don’t need to upgrade their technology in order to handle these transactions, Send Chinatown Love manages all of it and then pays each restaurant 100% of the proceeds in casha major factor that sets this effort apart from other fundraising organizations, because they meet restaurants’ needs using the technology that they already have."},{"type":"h2","text":"Marketing"},{"type":"p","text":"Send Chinatown Love also handles all the marketing for these businesses so they don’t have to take on the financial burden of starting and conducting successful advertising campaigns. This way they can build an online presence without having to pay for a new system, upgrade their technology or invest money in getting new customers. This is especially important now when restaurants desperately need business but don’t have spare money to run their own campaigns."},{"type":"p","text":"In addition to handling all of the social media marketing for these companies, Send Chinatown Love develops SEO on the new websites thus making them more widely discoverable on search engines and ensuring they’re included in directories of other local businesses nearby."},{"type":"p","text":"Send Chinatown Love doesn’t just set up these programs; they also run them on the restaurants’ behalves. Additionally, they teach the restaurant staff how to use their new voucher program and even hand-deliver them the proceeds in cash or check so they don’t need to worry about having a compatible POS system for payment. These restaurants don’t have to take credit cards at all and can continue operating off-the-grid."},{"type":"h2","text":"Other Initiatives"},{"type":"p","text":"Aside from setting up marketing channels and webpages for Chinatown restaurant, the organization also works in other ways to assist small business owners in the community. They seek a good way to help restaurants affected by the pandemic while still protecting their own employees’, as well as their customers’, continued health and safety. That’s why they additionally…"},{"type":"p","text":"1. Built a resource center that provides help in both English and Chinese."},{"type":"p","text":"To best ensure their merchant partners get the best assistance possible, they’ve staffed their resource center with both English and Chinese speakers so they can communicate more effectively with restaurant partners. This center teaches restaurants how to reopen and restructure after the COVID-19 pandemic is over, helping them prepare for a more successful future."},{"type":"p","text":"1. Encourage restaurants to set up delivery."},{"type":"p","text":"Restaurants all over the world are generating additional revenue throughout this pandemic by setting up delivery systems. When takeout services aren’t enough, delivery can help create additional revenue streams after dine-in services are forced to close or operate at reduced capacity. Delivery is an effective way to continue serving loyal customers without compromising social distance measures."},{"type":"p","text":"1. Design merchandise."},{"type":"p","text":"Send Chinatown Love makes merchandise for every individual restaurant partner, opening yet another revenue stream for them. Additionally they use logos and other popular aspects of these businesses to promote them on social media and create specialized merchandise that will best appeal to their loyal customers."},{"type":"p","text":"1. Gift-a-meal program."},{"type":"p","text":"They’re working on setting up a gift-a-meal program which will allow customers to buy someone else food. They’re aiming to direct this program at Chinatown’s senior population and well as families in the community who lost work because of COVID-19."},{"type":"p","text":"1. Work with restaurants to build the resources they need."},{"type":"p","text":"Every business has its own diverse set of needs and wants. For example, some aren’t comfortable accepting donations so the organization only sets them up to accept gift cards. Later, once the owners recognize that Send Chinatown Love is willing to do all of the work for them and trusts that they have these businesses’ best interests at heart, they are more receptive to other beneficial channels that the organization suggests."},{"type":"p","text":"Get Involved"},{"type":"p","text":"Send Chinatown Love is looking for volunteers to assist their efforts. Unlike many other initiatives they’re not in need of healthcare workers, food runners or people to pack meals. Instead they recruit software engineers, illustrators, product designers and more so they can continue designing webpages and setting up online ordering systems for merchants affected by COVID-19 in Chinatown."},{"type":"p","text":"They’re also calling for speakers and translators fluent in Mandarin, Cantonese, Korean, Japanese, Vietnamese, Thai, Tagalong or other languages spoken in East or Southeast Asia. The initiative works to help businesses in their language, in their way. They specialize their assistance to each restaurant’s individual needs, and those intricacies can best be communicated in their native tongue."},{"type":"p","text":"Individuals and organizations hoping to partner with Send Chinatown Love can join the effort by raising awareness and letting people know that this organization exists as well as what they’re doing to support the community. Doing so helps restaurants connect with the organization and also informs individuals about the cause so that they can reach out and notify businesses they know would benefit from this assistance."},{"type":"p","text":"Send Chinatown Love keeps a running update on their website about how much money they’ve raised, how many restaurants they’ve helped and the total amount of vouchers and donations sold. Since their launch, they’ve helped restaurants garner nearly $8K. They’re continuing to help individuals in the New York community gain access to their services via promotions. They’ve even added Black Lives Matter resources to their website beside the links published about the pandemic."},{"type":"p","text":"They pour their time and resources into helping the Chinatown community and specifically small businesses and restaurants struggling throughout this tumultuous time. Consider donating your time and resources, too, if you’re able, by buying vouchers, gift cards or sending donations to Chinatown restaurants in need. Help out here."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #CoronavirusPandemic #Covid19Pandemic #FoodService #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_48456f49a84c4b19a7d8e4ce8f638469~mv2.png', 'Point of Sale', 'eatOS Staff', '2022-07-01', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('community-highlight-st-mary-s-food-bank-alliance', 'Community Highlight: St. Mary’s Food Bank Alliance', 'Nonprofit organizations that distribute food, collect money and deploy volunteers are extremely important to getting families the supplies they need. Because of the COVID-19 pandemic, more people than ever need...', '[{"type":"p","text":"Nonprofit organizations that distribute food, collect money and deploy volunteers are extremely important to getting families the supplies they need. Because of the COVID-19 pandemic, more people than ever need assistance and support. Those nonprofit groups have had to adapt their organizational strategies and their volume of output in order to provide the relief that their communities have come to both expect and depend on."},{"type":"p","text":"St. Mary’s Food Bank Alliance based in Phoenix, AZ is one such organization. Before the pandemic, they served between 500 and 600 people every day. Now they average twice that, and sometimes more. Every day they work extremely hard to keep up with such enormous demand."},{"type":"h2","text":"Get Involved"},{"type":"p","text":"As an essential service, St. Mary’s Food Bank has remained open throughout this crisis and plan on staying that way for as long as they have supplies. This pandemic naturally breeds uncertainty: No one has a clear-cut timeline of how long it will continue but endless amounts of people need help. To keep programs like this going, St. Mary’s Food Bank has opened itself up to any assistance that community members can afford."},{"type":"p","text":"With offices in Phoenix, Surprise and Flagstaff, they have multiple opportunities on their website on the “Get Involved” page."},{"type":"p","text":"1. Donate"},{"type":"p","text":"Since the pandemic began, donations to this cause have already increased significantly. According to one client center manager, they’ve been getting contributions “by the truckloads,” which lets them continue providing baskets full of supplies to everyone who visits the food bankdespite serving approximately 1200 people every day, and often even more. The lines are extremely long and they need everything they can get just to keep up with demand."},{"type":"p","text":"Donations start at a minimum of $5. They also suggest larger figures but you can customize your donation to whatever you can afford. Along with the dollar amount, the suggested donations tell you how many meals it will provide for people in need."},{"type":"p","text":"1. Volunteer"},{"type":"p","text":"They have many volunteer opportunities available for anyone hoping to get involved with these relief efforts. You can host food drives on behalf of St. Mary’s, start collection boxes, attend or help set up events, and raise additional donations for the cause."},{"type":"p","text":"The nonprofit also has advocacy opportunities available. They’re looking for people to help garner political support for the legislation that they back, which means calling state and local representatives and encouraging them to endorse programs like Child Nutrition Reauthorization, hunger relief and nutrition efforts, and tax policies that support food banks and similar organizations."},{"type":"p","text":"1. Company support"},{"type":"p","text":"In many cases, big businesses have more opportunities and significantly more resources to assist those who are struggling. That’s why St. Mary’s Food Bank has a section for companies that want to help: Companies can donate larger amounts, host funds and food drives, and organize mass volunteering efforts. They can also run marketing campaigns, become a food industry partner and help coordinate off-site events to spread St. Mary’s advocacy efforts throughout Arizona at large."},{"type":"p","text":"Check out the Workplace Giving section of their website to learn more about how your company can get involved."},{"type":"h2","text":"Need Help?"},{"type":"p","text":"Many people struggle to support their families because of this pandemic, and St. Mary’s Food Bank Alliance aims to help relieve some of the pressure. Arizona residents will need to travel to an offices or food banks for assistance, so the website has multiple channels to direct people in need to locations near them."},{"type":"p","text":"The “Get Help” page tells people where to find food boxes, food pantries, soup kitchens, shelters and similar locations by redirecting them to the Arizona Food Bank Network. This network connects people not just to St. Mary’s Food Bank but also other associated nonprofits in the state. People can also check their eligibility for government assistance programs like SNAP."},{"type":"p","text":"Additionally St. Mary’s Food Bank provides resources geared toward specific demographics. For example, they display phone numbers for the AZ Hunger Hotline which has resources for feeding minors. They also help seniors find out if they’re eligible for the Commodity Supplemental Food Program. They have many additional resources available to provide information, benefits and redirection to other assistance services that help families and individuals in needwhether their situation is a direct result of COVID-19 or not."},{"type":"p","text":"Additionally, their Mobile Pantry brings to even more relief to Arizonans in need. The truck travels around the state and sets up open air markets where people can go to acquire produce and other fresh groceries. Recipients “shop” there for free. They don’t need to have any proof of residency or ID; the lack of a vetting system ensures that everyone can get food without worrying about identification or “proving” the depth of their need. The time and location of where the Mobile Pantry will be next is up on the food bank’s website, along with the schedules of other fundraising events hosted by St. Mary’s Food Bank."},{"type":"p","text":"St. Mary’s Food Bank Alliance takes their own precautions to protect volunteers and recipients from COVID-19. To supplement these efforts, AZ Food Bank Network also sent out a notice to their associated nonprofits with recommendations for quelling the virus. These include tips for managing the team, cleaning and sanitation techniques, and advice for assessing and handling anyone displaying or reporting symptoms."},{"type":"p","text":"In line with that goal, St. Mary’s Food Bank asks volunteers not to join the cause in person if they’ve recently visited an area with many confirmed cases of the virus; been within six feet of someone sick with COVID-19; or begun displaying symptoms such as a fever, shortness of breath, coughing and other respiratory issues, sore throat or other symptoms commonly associated with COVID-19."},{"type":"p","text":"If you can, get involved in supporting the Arizona community during these difficult times. Even if you can’t give your time, consider donating money or food to the drive. Every contribution helps, especially in light of the sheer volume of people relying on them for support every single day. St. Mary’s Food Bank Alliance and organizations like them work hard to do their part for their communities."},{"type":"p","text":"Donate now or visit their website to find out how you can help."},{"type":"p","text":"#CommunityOutreachStrategies #CoronavirusPandemic #Covid19Pandemic #Nonprofit"}]', 'https://static.wixstatic.com/media/a77ed6_25b651cffaec4b138d0712025948bf70~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2022-06-29', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('community-highlight-stony-brook-university', 'Community Highlight: Stony Brook University', 'Everyone, including the students on campus, take classes online but those staying at the university still need to eat. The university thus devised two safe avenues for their students to get three meals a day without...', '[{"type":"p","text":"Everyone, including the students on campus, take classes online but those staying at the university still need to eat. The university thus devised two safe avenues for their students to get three meals a day without risking the health and safety of themselves or the university staff."},{"type":"h2","text":"GET Mobile App"},{"type":"p","text":"Students can order snacks and essential items from on-campus stores through Stony Brook’s GET Mobile app. This way, when they need to make retail purchases, they don’t have to go out in public and risk exposure. Through the app, students can order cleaning supplies, toiletries, oatmeal and even cold cuts. So many essentials are gone from traditional stores anyway; shelves across the country have only just begun to restock small amounts of paper towels, toilet paper and the like. With GET Mobile, students they don’t have to go without necessaries like these."},{"type":"p","text":"The app connects from the university’s Market store, certain Starbucks locations and other campus retail to give students access to a variety of groceries and essential items. They can pay for these supplies with their Wolfie Wallet university debit account, their Dining Dollars meal plan, or regular credit and debit cards connected to their bank accounts."},{"type":"p","text":"The GET Mobile App allows students to remain isolated without sacrificing their safety or peace of mind. Additionally, the variety of acceptable payment methods means that their Wolfie Wallet balance and the Dining Dollars that they purchased at the beginning of the semester doesn’t go to waste; instead, they have a way to use what they paid for and get what they need simultaneously."},{"type":"h2","text":"Brand New Dining Halls"},{"type":"p","text":"Two of Stony Brook’s dining halls, East Side and West Side, remain open for use. Keeping these functional allows students to get three square meals a day without constantly paying for groceries, and also accommodates people who don’t have the money to constantly buy food or a kitchen to cook in."},{"type":"p","text":"Thus the university temporarily reorganized their dining hall system to protect both students and workers. They’ve implemented the following changes:"},{"type":"p","text":"1. Students can come in, pick up their food and bring it back to their housing. They no longer have the option to sit down and eat in the dining hall. This will stop people from packing close together for long periods of time."},{"type":"p","text":"2. Additionally, the dining hall now has markers on the floor so students can stay six feet apart and maintain a safe distance from one another."},{"type":"p","text":"3. No one swipes IDs anymore; rather, students enter the facility by scanning a barcode on their phone. This cuts down on interactions between students and workers and prevents them from passing items back and forth."},{"type":"p","text":"4. Hand sanitizer has been stationed outside both buildings so that students can safely apply some before and after entering either facility."},{"type":"p","text":"5. Everyone gets disposable gloves when they arrive that they must keep on until after they’ve exited the building. This prevents everyone touching the same high-trafficked surfaces, such as door handles, with bare hands."},{"type":"p","text":"6. Each dining hall has an entrance open on one side of the building and the exit on the other. Everyone must go through the correct way to ensure students come in a single file line and avoid close contact as well as crowded doorways."},{"type":"p","text":"7. The menu rotates each day so students can have a varied diet. They always have kosher, halal and vegan options and the dishes served range from meat, vegetables, comfort food, dessert and more so everyone can find something to sate their appetite and fit their needs."},{"type":"p","text":"8. Dining hall staff fills a takeout container with food as students go down the line picking what they want. This reduces how many people touch the container in total and prevents students from all handling the same utensils."},{"type":"p","text":"Stony Brook University has instituted such developments so that they can continue accommodating their 2K on-campus residents through the rest of spring semester. In addition to these changes, they’ve also have other protocols in place for students who get sick with COVID-19 or any other illnesses."},{"type":"p","text":"First the university will direct them to the nearest student health services center. People can also procure a Sick Tray Form from their R.A. or residence hall director, which allows a friend to pick up dining hall food for them and deliver it to their door. To further spread applicable information, the front page of the dining services website rotates out informational messages that detail New York’s COVID-19 safety protocols so students can better protect themselves and prevent the spread of the virus."},{"type":"p","text":"Stony Brook University, like many other colleges around the world, have to adapt to this new COVID-19 normalcy wherein some students remain on campus and need applicable accommodations. In these cases, universities all over are making the necessary changes to ensure their students can continue to eat three square, healthy meals a day. Universities need to ensure the continued care and protection of their students without sacrificing their welfare of that of university employees."},{"type":"p","text":"As we continue to adapt to COVID-19 and come to better understand the long-term adjustments that are needed to ensure everyone still has access to basic necessities, Stony Brook University demonstrates the level of care that similar institutions can take to support their students through the rest of the school year."},{"type":"p","text":"#CoronavirusPandemic #Covid19Pandemic"}]', 'https://static.wixstatic.com/media/a77ed6_27a3ff025e544f41b455737cfe07b449~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2022-06-24', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('community-highlight-white-pony-express', 'Community Highlight: White Pony Express', 'Many outreach organizations have been appropriately recognized for their contributions to people and communities in need during this COVID-19 pandemic. In April 2020, _Time_ magazine created a special edition article...', '[{"type":"p","text":"Many outreach organizations have been appropriately recognized for their contributions to people and communities in need during this COVID-19 pandemic. In April 2020, _Time_ magazine created a special edition article complete with five different covers and twelve stories showcasing the incredible work people have done, appropriately titled “Heroes of the Front Lines.”"},{"type":"p","text":"Weve already written about some of the amazing workers who made the cover. Less discussed, however, is the hard work of the eleven other essential workers described in the article. One of them, spotlighting a man employed by White Pony Express, describes the intense, necessary work done by the food rescue and recovery program."},{"type":"h2","text":"Who is White Pony Express?"},{"type":"p","text":"This nonprofit group based in Pleasant Hill, CA provides food and other necessaries to people who need them. They deliver to people and partner organizations in Contra Costa County, fighting poverty in their community."},{"type":"p","text":"They don’t just deliver food; they also believe that clothing and other basic items are a human right. So many businesses produce in excess and have nothing to do with the leftovers that they can’t sell; they want to contribute to those in need but unfortunately don’t have spare time to dedicate to outreach. Thus they connect with White Pony Express who can pick up donations from the source and deliver the groceries and other necessities directly to those in need."},{"type":"p","text":"White Pony Express also accepts donations from the general public. Anyone can give money, food, clothes and more; since they work with such a variety of generous organizations who support many different people, White Pony Express welcomes all kinds of gifts."},{"type":"p","text":"In addition to hand-delivering donations to individuals and organizations, they also run the White Pony General Store, which according to their website “distributes new and like new clothing, shoes, toys, childrens books and games to our Contra Costa neighbors in need. WPGS partners with local businesses, clothing retailers and individual donors to sort, organize and deliver high quality goods free of charge. To supplement the good done by the store, they also run a Mobile Boutique that’s functionally the same: Dedicated workers travel to set up temporary stores in lower-income areas that need their help. Anyone can come “shop” there, though really the General Store, like the organization at large, doesn’t actually charge anyone money for receiving these donations."},{"type":"p","text":"In the five years they’ve been in operation, White Pony Express has delivered over 9M pounds of food to people in need. Since the COVID-19 pandemic began, they’ve increased their productivity and expanded their scope to do everything they can for those struggling during this time."},{"type":"h2","text":"What they’re doing now"},{"type":"p","text":"Since COVID-19, more people than ever need help from generous organizations like White Pony Express. That’s why they’ve increased their workload to provide what’s needed. On April 9th, when the _Times_ article came out, they were redistributing 17K pounds of food every day. To put that in perspective, they traditionally only rescue 6K pounds per day under normal circumstances. Of course, the world right now is anything but normal."},{"type":"p","text":"Their workers and volunteers still work as hard as ever, not because they have to, but because many simply care that deeply for what they do. In fact, some take the mission very personally: for example Cliff Strand Jr., the worker who _Time_ interviewed for the article, was saved by the organization before he started working with them. Now he’s joined up and, in his words: “This is absolutely my mission. Its not a job. Im supremely blessed to be able to do this."},{"type":"p","text":"White Pony Express also gets close to the people that they help. They deliver to shelters, kitchens and similar organizations, but they also give baskets of food and other necessities directly to those in need. That’s how Cliff Strand Jr. first met them; an executive from the mission found him and brought him what he needed to survive. Ultimately, their help enabled him to turn his life around. Now he’s paying it forward."},{"type":"p","text":"With the workers and volunteers pushing themselves harder than ever, they have to take extra safety precautions to prevent the possible spread of COVID-19. They want to help their community, not contribute to the problem. Thus everyone wears masks, changes gloves at each location they visit and takes all the mandated precautions against spreading the disease. Additionally, White Pony Express has added a “COVID-19 Rapid Response” page beneath the Donate tab on their website, which lays out the following information:"},{"type":"p","text":"1. The reasons why they need supplies more than ever right now. The pandemic has created a scarcity, wherein more people than ever need essentials but have less income to acquire them, and businesses have less excess as they reduce their output or shutter their doors completely."},{"type":"p","text":"2. An explanation of what supplies they’re lacking and the funding required to cover it."},{"type":"p","text":"3. How to donate and volunteer."},{"type":"p","text":"4. Other ways to help the organization."},{"type":"p","text":"As this pandemic stretches on, organizations like White Pony Express continue to do the most important work of all: assisting those most vulnerable in the community. They’ve demonstrated what compassion, drive and dedication can do to push outreach efforts to new heights."},{"type":"p","text":"Now more than ever, people need a helping hand. In this crisis, anyone channeling the same efforts and care as White Pony Express is a hero on the front line."},{"type":"p","text":"#CommunityOutreachStrategies #CoronavirusPandemic #Covid19Pandemic #Delivery"}]', 'https://static.wixstatic.com/media/a77ed6_83fa657cb1514144ac652b3590c9110f~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2022-06-23', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('contactless-service-comes-to-breweries', 'Contactless Service Comes to Breweries', 'During these past months of the COVID-19 pandemic, businesses have opened and closed and opened and closed, trying to weather the financial trouble that comes from limited business operations. Many of them were unable...', '[{"type":"p","text":"During these past months of the COVID-19 pandemic, businesses have opened and closed and opened and closed, trying to weather the financial trouble that comes from limited business operations. Many of them were unable to find a sufficiently viable solution that didn’t lead to more sickness and death in their communities. It’s a difficult and delicate line to walk, but those that found the most success did so by leaning into contact-free ordering systems that prioritize the health and safety of customers and staff members alike."},{"type":"p","text":"It’s easy for some nonessential businesses to make changes like having their employees work remotely and implementing stringent social distancing measures, but that’s hard to do for a lot of the service industry. In restaurants and bars, the quality of customer service makes or breaks a reputation, and reputation, which is highly dependent on face-to-face interactions between servers and customers, directly influences the bottom line."},{"type":"p","text":"Technology is doing its best to adapt to the current situation, and as months go by, the restaurant tech industry has come up with more and more solutions to handle the pressing question of how to balance safety with salesand getting better at it all the time."},{"type":"h2","text":"Temescal Brewing"},{"type":"p","text":"In the Bay Area of California, Temescal Brewing wasn’t the only company forced to rethink their business approach after that first, massive wave of shutdowns came for them in March. They finally got the chance to reopen for good in July, although their journey was fraught with trouble: Initially prepared to reopen seating at limited capacity on July 11th, the county announced late the night before that they would once again shut down outdoor dining, which threw a wrench late in their plans. However, the delay ultimately gave the brewery more time to prepare for the relaunch, making sure they could hit the ground running when the time came. The county successfully petitioned the state health department to get the shutdown repealed, and by July 15th, beer al fresco was on the table once againliterally."},{"type":"p","text":"Those few extra days gave Temescal the time they needed to perfect their approach. Now they have a completely contact-free method for serving craft beer to their eager customers, in the hopes that all this automation and security will keep everyone safe enough to avoid another closure in the future."},{"type":"p","text":"First, Temescal eliminated indoor ordering, thus reducing the risk that customers take by staying with them. All seating takes place outdoors in their beer garden and patio, making it easier to socially distance tables and keep customers apart. Additionally, the lack of circulated air means customers are much less likely to spread any germs they might have."},{"type":"p","text":"Temescal is also following all the state guidelines; California’s Alcoholic Beverage Control made rules in March mandating that any establishment serving drinks could only stay open if customers could get food there, too; in a mutually beneficial agreement, Temescal Brewing partnered with Roli Roti, a rotisserie food truck on the premises, so as to meet these mandates. They now require that every customer buys a meal ticket, too."},{"type":"p","text":"Interestingly, throughout COVID-19 theres been a massive shift in consumer attitudes regarding customer service. Traditionally in the past, good service was defined by face-to-face contact between guests and waitstaff, judged by the quality of those interactions and speed and ease of service. Many customers are concerned with the amount of back-and-forth their server may have had with others throughout the day, though, and employees are extremely worried about all that exposure when they don’t have the option to stay home or find another job in the midst of a massive pandemic and economic recession which may, any day now, tip over into an outright depression."},{"type":"p","text":"Thus Temescal took a different approach: They eliminated waitstaff when they reopened and replaced them with the Beer-O-Mat. Thats not the say they fired employees; on the contrary, they were able to keep everyone on staff and simply reassign their positions and day-to-day tasks to make for a better, safer work environment."},{"type":"p","text":"The structures name walks the line between high-tech and too serious, but it’s actually more fun and light than it sounds; the Beer-O-Mat is just a big, green-and-pastel-pink construction that every brewery can create some variation of to similarly limit dangerous face-to-face contact. Inspired by the automats of old, it amounts to a series of cubbies with plexiglas barriers where customers can grab their drinks, but as simple as it sounds, it adds a layer of extra protection that makes it just that little bit safer to reopen during a global pandemic."},{"type":"p","text":"Of course other breweries can design their own version of the Beer-O-Mat to fit their brand and audience; Temescal specifically intended it to be a little bit silly. Sam Gilbert, the cofounder of the company, said of the monolith: “Rather than setting up a table where people could just come and grab a beer, we wanted to … add a little bit of whimsy to what is a very different experience for people.”"},{"type":"p","text":"The Beer-O-Mat is perfectly in line with the vibe of the brewery, whose regular decals include bananas, cactuses and amusing signage like “NO JERKS.” Anyone who wants to follow in their footsteps and take similar measures during their reopening can build their own Beer-O-Mat that matches the decorative scheme and tone that their particular brewery wants to convey."},{"type":"h2","text":"Beer-O-Mat and social distance"},{"type":"p","text":"Their efforts at shielding employees would be incomplete without taking additional steps to provide a safe and sanitary experience. From start to finish, Temescal makes sure every customer feels as safe as possible drinking with them. Here’s how it works:"},{"type":"p","text":"1. A host greets customers at the entrance and assigns them a table, where they remain for the duration of their stay."},{"type":"p","text":"2. Customers order at the entrance as well by scanning a QR code on their phone. They enter their name and payment information on that screen and choose their beer too, finishing the entire transaction right then and then."},{"type":"p","text":"3. When the order is ready, customers get a text telling them to go pick up their beer at the Beer-O-Mat. Compartments are labeled by table number, which is why it’s so important to stay where the host assigns youand also because it reduces the risk of germs, of course, which can spread by touching the same table as another customer before it’s sanitized."},{"type":"p","text":"4. At the back of each cubby, a sliding plexiglass panel lets employees put each beer safely in their assigned spot for the customer to grab."},{"type":"p","text":"For the time being, Temescal is only serving canned beer, probably because they’re not reusable and thus don’t carry the inherent risk that all multi-use items do. Customers cant spread germs if there are no shared surfaces to touch."},{"type":"p","text":"Temescal’s Beer-O-Mat especially stands out because they managed to corner the intersection of functionality and fun. Its lighthearted exterior holds a genuinely good design that protects customers as well as staff, which is great because employees’ safety often isn’t a big factor when considering how to reopen in a way that’s compliant with local and state guidelines."},{"type":"h2","text":"The future of breweries"},{"type":"p","text":"Though figuring out the best way to prioritize safety concerns took awhile, the extra time gave Temescal Brewing the opportunity to find something that really worked; meanwhile, others are struggling because they try to open as fast as possible, taking the easy way to get it done quickly rather than really hammering out effective solutions that assuage the public’s concerns about health and safety. Ultimately this just costs more time and money, and a lot of businesses end up bankrupt and shut down forever."},{"type":"p","text":"Temescal has other advantages that keep them afloat when other breweries, bars, and restaurants can’t manage: Loans from the Paycheck Protection Program. Although many small businesses applied for PPP loans, Temescal Brewing is one of the lucky few who actually received one; thus they were able to rehire and keep all of their staff throughout these many months of unsureness and struggle to get to where they are now."},{"type":"p","text":"They keep their patio open on weekends only, to reduce some of the crowds; customers can enjoy a cold beer there every Thursday and Friday from 4 to 8:30PM or Saturday and Sunday between 3 and 9PM. That and the beer garden will stay open through the rest of the summer."},{"type":"p","text":"They also have a pickup service available for those who don’t want to stay and enjoy the atmosphere they’ve cultivated outdoors. The pickup area is also behind a Plexiglas barrier and has a kiosk for customers to use, though they have to order online first before they come onto the premises."},{"type":"p","text":"Temescal Brewing has walked the line between safety precautions and a fun, lighthearted atmosphere. Following protocol doesn’t have to be dreary, and ensuring the continued good health of everyone involved with or around your business doesn’t mean giving up brand identity. You dont have to forgo any of the reasons that you, as a business owner, began your brewery in the first place. It’s a new ageand breweries need to learn how to handle COVID-19 safety procedures with as much weight as they give the rest of their business operations. Temescal’s Beer-O-Mat, in all its amusing but effective glory, is the lighthouse beckoning in the future of brewery service."},{"type":"p","text":"#CoronavirusPandemic #FoodService #FoodServiceTechnologybyeatOS #HealthandSafety"}]', 'https://static.wixstatic.com/media/a77ed6_a37199f19e8941c1b6d2b72d530609a6~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2022-06-21', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('covid-might-change-how-restaurants-tip-out-their-workers', 'Covid Might Change How Restaurants Tip Out Their Workers', 'Doubtlessly COVID-19 has changed the foodservice industry’s landscape since it took over everyone’s lives last March. As case numbers rise and fall, and legal policies surrounding restaurants and public safety evolve in...', '[{"type":"p","text":"Doubtlessly COVID-19 has changed the foodservice industry’s landscape since it took over everyone’s lives last March. As case numbers rise and fall, and legal policies surrounding restaurants and public safety evolve in response, employees in one of the country’s biggest industries are concerned about a steady paycheck. COVID-19 has left many unemployed, with restaurants and bars accounting for 25% of lost jobs during the height of the pandemic."},{"type":"p","text":"Previous to this “new normal,” tipping was a regular practice at almost any restaurant. The federal tipped minimum wage allows businesses to pay their employees $2.13/hr as long as their monthly tips make up at least the difference that they would earn under regular minimum wage in their state. With the added emotional stress of the pandemic, lost hours and jobs, financial difficulties, and reduced capacity regulations, servers are starting to come together and collectively say: Tips alone just aren’t meeting the cost of living nowadays the age of this management model might be over."},{"type":"h2","text":"The Death of Tipping"},{"type":"p","text":"Appropriate staff payment models have been a hot-button issue for years. Many waiters have reported that they don’t take home enough at the end of the day, which is why employee turnover is so high in the hospitality industry."},{"type":"p","text":"At the beginning of 2020, tips increased on average. People initially thought that the pandemic would be a short-term issue and thus gave more than usual in the spring, feeling for the financial difficulties that restaurants and their employees were going through at the time, aware that the shift to takeout and delivery hit everyone hard. Now, so many months in, customers are struggling with money and can’t afford to pay restaurants’ employees for them."},{"type":"p","text":"Part of the issue is that food service workers are having trouble getting their jobs back, and when they do, they get limited hours. Restaurants are closing en masse because of decreased profits (a result of losing dine-in service) and little government intervention, and those that remain open do so for limited hours. Half of the restaurant employees who went back to work report getting scheduled for ten or fewer hours each week. Meanwhile, when they get shifts, employees have to contend with health and safety concerns on the job and enforce most of the COVID-19 regulations themselves, dealing with customers who don’t want to follow mask rules and potentially put their wellness at risk."},{"type":"p","text":"Most of the time, though, it boils down to the fact that customers simply aren’t pouring into dine-in like they used to. They’re not comfortable sitting in a public, enclosed space for a long time, but servers don’t benefit from tips spent on takeout and delivery orders. Since COVID-19 began, 65% of service workers say their tips have been cut in two. Nearly half say they’ve lost the majority of their tips because of this pandemic. As the winter months close outdoor seating options (one of the last vestiges of dine-in services), it may be time to revisit whether tipping remains a viable business model at all."},{"type":"h2","text":"Alternative Models"},{"type":"p","text":"When tipping just isn’t working anymore, you can take care of your employees by pivoting to a better option, such as…"},{"type":"p","text":"1. Raising base pay and eliminating tips. When you raise menu prices to reflect a living wage, gratuity-free models make more sense. Some places are already instituting covid surcharges; for example, in New York City, they’ve increased each bill by 10%. You can also raise prices and put the additional revenue toward payroll, although it’s best to be honest and transparent with guests about why their prices are rising so you don’t get as many complaints about the higher costs."},{"type":"p","text":"2. Changing your current tip system. For example, suppose your servers usually take home all their tips, but money’s tight because of new state policies or sanitation procedures. In that case, you might consider switching to a tip pooling structure so waitstaff, delivery couriers, back of house, and the whole team gets a cut of some or all of the night’s tips. Whatever tipping structure you use should motivate your entire team to work together and sell more rather than causing additional tension."},{"type":"p","text":"3. Talking to your employees. As the ones working the floor every day and chatting with your best customers face-to-face, your servers will have strong opinions on which tipping model most effectively encourages productivity. Some servers and bartenders prefer tips to a salary so they can take home their cash at the end of each night; some would much rather have a steady paycheck, so they can manage their monthly budgets. It all depends on personal experience and expectations, so reach out and communicate openly with your staff. Establishing an honest back and forth is the foundation of robust work environments."},{"type":"p","text":"At eatOS, we power technology that’s designed to help you make safer, more profitable business decisions. From real-time reporting features that make budgeting a breeze to an easy-to-learn interface for smooth delivery integration, your customers will appreciate the versatility of faster service. At the same time, employees benefit from easier tipping, if you choose to stick out the model after all."},{"type":"p","text":"You might find you have the finances you need to pay a living, base wage to all of your servers when you invest with eatOS. Our superior management software seamlessly opens online ordering revenue streams, where you keep all the tips: No more paying out towering third-party commission fees. With more profit in your pocket, you can offer competitive salaries to draw in the best of the best candidates. Greater rewards entice more productive workers to your payroll."},{"type":"p","text":"When it comes down to it, the pandemic has changed how we approach every aspect of running a restaurant. Servers need sustainable, living wages. Customers need affordable, safe dining options, and they’re less able than usual to pay more in tips when employees deserve it. It would help if you maximized revenue, mainly when sales are thin all over the country."},{"type":"p","text":"eatOS is the answer. Schedule a demo with us today and see firsthand how we’ll help your team collaborate more efficiently, streamline overall operations and automatically calculate tips and paychecks no matter what tipping model you ultimately structure inside your restaurant. Restaurant management just got made simple."},{"type":"p","text":"#eatOS #CoronavirusPandemic #Tips #Covid19Pandemic #RestaurantBusiness #Restaurant #StaffingampRecruiting"}]', 'https://static.wixstatic.com/media/a77ed6_d4ec2ba58e074f4e8614c06cf41266eb~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2022-06-17', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('delivery-co-ops-the-answer-to-high-commission-fees', 'Delivery Co-Ops: The Answer to High Commission Fees?', 'During the height of the COVID-19 pandemic, food delivery took off. With dine-in restrictions in place, restaurants needed a surefire way to make money. Meanwhile customers still enjoy the ease and efficiency of...', '[{"type":"p","text":"During the height of the COVID-19 pandemic, food delivery took off. With dine-in restrictions in place, restaurants needed a surefire way to make money. Meanwhile customers still enjoy the ease and efficiency of ordering their favorite restaurants right to their door. As one of the few socially distant options available, takeout and delivery have grown enormously this past year."},{"type":"p","text":"For restaurants who maybe never offered delivery before, or at least didn’t focus that heavily on it, they needed a rapid way to pivot. Third party delivery apps offered this exact scenario: It was an attractive option at the beginning of COVID-19, when no one quite knew how to handle closures and didn’t have a ton of time to find out. Opening new delivery streams also costs a lot. Even now, restaurants struggle to get back to the (relative) financial stability they had pre-pandemic."},{"type":"p","text":"The problem with third parties is that they can get pretty expensive, too. Some restaurants report fees as high as 30%. Thus, business owners needed another solution. Some found it in joining together."},{"type":"p","text":"Photo by Rowan Freeman on Unsplash"},{"type":"h2","text":"What Are Delivery Co-Ops?"},{"type":"p","text":"When you think about co-ops, food delivery may not be the first thing that springs to mind. They’re member-owned and -controlled, so those with invested interests can control how the organization works. They all use and benefit from the co-op; with food delivery, that means many local restaurants band together to create a delivery service that they all share. Everyone gets to use the couriers, but everyone shares in the costs."},{"type":"p","text":"Delivery co-ops are already forming in many cities. These channels that hyperlocalize service. Then the restaurants get benefits like:"},{"type":"p","text":"1. lower service rates for customers,"},{"type":"p","text":"2. better pay for drivers, and"},{"type":"p","text":"3. higher percentage of profit for the restaurants themselves."},{"type":"p","text":"Even though they’re splitting the incoming revenue by tens or even hundreds of businesses (depending on where you’re situated), you still pull in more than you would with most third parties."},{"type":"p","text":"Meanwhile, companies can make sure that their employees are treated fairly and inclusively. They don’t have to entrust their workers’ care to outside parties, particularly given that the industry is rife with inequality. They set the rules, and that can mean taking better care of employees."},{"type":"h2","text":"Delivery Co-Ops and the Future"},{"type":"p","text":"They’re popping up all around the U.S. for a reason: They’re working. Delivery co-ops are a great way to open much-needed sales channels without breaking the bank on commission fees. But they’re not the only alternative."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #FoodDelivery #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_fe9c38daaace4047b364bda658c7f6a1~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-06-15', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('why-restaurants-want-direct-delivery', 'Why Restaurants Want Direct Delivery', 'When COVID-19 first began, restaurants learned to turn their attention to off-premise ordering channels. By summer, takeout services reigned supreme. From their end, customers got used to the ease and efficiency of...', '[{"type":"p","text":"When COVID-19 first began, restaurants learned to turn their attention to off-premise ordering channels. By summer, takeout services reigned supreme. From their end, customers got used to the ease and efficiency of scrolling through the apps. During this surge in popularity, restaurants continued to struggle with razor-thin profit margins. Now, they’re looking at direct delivery instead."},{"type":"p","text":"Although pickup and curbside also got more popular this year, delivery in particular really drives revenue. That’s why so many restaurants signed up with third-party apps initially. Signing up for third parties automatically opens businesses up to a whole new audience of potential customers and also lets them reap the benefits of takeout sales without an expensive setup."},{"type":"p","text":"However, soon restaurants found themselves struggling with high commission fees, a lack of data sharing, and less control over the whole process."},{"type":"p","text":"Photo courtesy of eatOS"},{"type":"h2","text":"Direct Delivery Gives You the Data"},{"type":"p","text":"The more customers spend, the more detailed sales reports you’ll get. Analytic reports tell you what people buy the most and when they come by. When restaurants partnered with third-party apps, they found that the platforms didn’t share that crucial data. Thus those outside services could use the information to their own advantage, unfettered."},{"type":"p","text":"However, direct delivery gives you the reins. Access all that good customer data to build better marketing campaigns geared toward your most loyal guests. With the money saved on commission fees, invest some toward digital marketing. Become more discoverable and draw new customers right to your business. Instead of third-party apps deciding who gets the most attention, elevate your brand above the rest with direct delivery."},{"type":"h2","text":"Control the Direct Delivery Process"},{"type":"p","text":"Partnerships with third-party platforms also mean handing over the only face-to-face part of delivery left intact (assuming the customer doesn’t choose a contactless handoff). With your name on the takeout bag, you want to make sure everything goes smoothly, especially in case they complain. Handle all problems swiftly and effectively when you retake control of all your sales channels."},{"type":"p","text":"Although investing in new sales channels seems risky, it has a big payout when you do it right. Small restaurants can get in the game too. Sign up with eatOS and we’ll set up the new service as well as a branded mobile app designed just for your business. That way, you can focus on building the best restaurant that you can."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#eatOS #CoronavirusPandemic #PointofSaleforRestaurants #Covid19Pandemic #RestaurantBusiness #FoodDelivery #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_98080f44fa8745609908f20ffd054fef~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2022-06-10', 'published');
